// Har bir qurilma uchun doimiy identifikator (bitta hisob = bitta faol qurilma nazorati uchun)
function getDeviceId() {
  try {
    let id = localStorage.getItem("revit_device_id");
    if (!id) {
      id = (crypto.randomUUID ? crypto.randomUUID() : "dev-" + Date.now() + "-" + Math.random().toString(16).slice(2));
      localStorage.setItem("revit_device_id", id);
    }
    return id;
  } catch (e) {
    return "dev-" + Date.now() + "-" + Math.random().toString(16).slice(2);
  }
}
const deviceId = getDeviceId();

function getAnalyticsSessionId() {
  try {
    let sid = sessionStorage.getItem("agy_analytics_session_id");
    if (!sid) {
      sid = "ses-" + Date.now() + "-" + Math.random().toString(36).substring(2, 10);
      sessionStorage.setItem("agy_analytics_session_id", sid);
    }
    return sid;
  } catch (e) {
    return "ses-" + Date.now() + "-" + Math.random().toString(36).substring(2, 10);
  }
}

function getClientDeviceInfo() {
  const ua = navigator.userAgent || "";
  const tgPlatform = (window.Telegram && window.Telegram.WebApp && window.Telegram.WebApp.platform) ? String(window.Telegram.WebApp.platform).toLowerCase() : "";
  
  let deviceType = "mobile";
  let os = "Unknown";
  let clientType = tgPlatform ? ("Telegram (" + tgPlatform + ")") : "Web Browser";

  if (/android/i.test(ua) || tgPlatform === "android") {
    os = "Android";
    deviceType = "mobile";
  } else if (/iPad/i.test(ua) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1)) {
    os = "iPad / Tablet";
    deviceType = "tablet";
  } else if (/iPhone|iPod/i.test(ua) || tgPlatform === "ios") {
    os = "iPhone / iOS";
    deviceType = "mobile";
  } else if (/Windows/i.test(ua) || tgPlatform === "tdesktop") {
    os = "Windows";
    deviceType = "desktop";
  } else if (/Macintosh|Mac OS X/i.test(ua) || tgPlatform === "macos") {
    os = "macOS";
    deviceType = "desktop";
  } else if (/Linux/i.test(ua)) {
    os = "Linux";
    deviceType = "desktop";
  }

  const w = window.innerWidth || (window.screen ? window.screen.width : 0);
  const h = window.innerHeight || (window.screen ? window.screen.height : 0);
  if (deviceType === "mobile" && Math.min(w, h) >= 600) {
    deviceType = "tablet";
    if (os === "Unknown") os = "Tablet";
  }

  return {
    sessionId: getAnalyticsSessionId(),
    deviceType: deviceType,
    operatingSystem: os,
    clientType: clientType,
    screenWidth: window.screen ? window.screen.width : w,
    screenHeight: window.screen ? window.screen.height : h
  };
}


// ======================================================
// HTML & JS ESCAPE UTILITIES
// ======================================================

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function escapeJsString(value) {
  return String(value ?? "")
    .replace(/\\/g, "\\\\")
    .replace(/'/g, "\\'")
    .replace(/"/g, '\\"')
    .replace(/\r/g, "\\r")
    .replace(/\n/g, "\\n")
    .replace(/</g, "\\u003C")
    .replace(/>/g, "\\u003E");
}

// Google Drive, Dropbox va boshqa rasm linklarini to'g'ridan-to'g'ri img src formatiga o'tkazuvchi funksiya
function formatImageUrl(url) {
  if (!url || typeof url !== "string") return "";
  let cleanUrl = url.trim();
  if (!cleanUrl) return "";

  // Google Drive: /file/d/FILE_ID
  const driveFileMatch = cleanUrl.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
  if (driveFileMatch && driveFileMatch[1]) {
    return `https://lh3.googleusercontent.com/d/${driveFileMatch[1]}`;
  }

  // Google Drive: id=FILE_ID
  const driveIdMatch = cleanUrl.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  if (cleanUrl.includes("drive.google.com") && driveIdMatch && driveIdMatch[1]) {
    return `https://lh3.googleusercontent.com/d/${driveIdMatch[1]}`;
  }

  // Dropbox (dl=0 -> raw=1)
  if (cleanUrl.includes("dropbox.com")) {
    return cleanUrl.replace(/[?&]dl=0/, "").concat(cleanUrl.includes("?") ? "&raw=1" : "?raw=1");
  }

  if (!cleanUrl.startsWith("http://") && !cleanUrl.startsWith("https://") && !cleanUrl.startsWith("data:") && !cleanUrl.startsWith("/")) {
    cleanUrl = "https://" + cleanUrl;
  }

  // Sanitize legacy placeholder developer photos
  if (cleanUrl.includes("1581094794329") || cleanUrl.includes("1534528741775") || cleanUrl.includes("1507003211169")) {
    return "https://images.unsplash.com/photo-1581858726788-75bc0f6a952d?w=600&auto=format&fit=crop&q=80";
  }

  return cleanUrl;
}

function getDriveFallbackUrl(url) {
  if (!url || typeof url !== "string") return "";
  let cleanUrl = url.trim();
  const driveFileMatch = cleanUrl.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
  if (driveFileMatch && driveFileMatch[1]) {
    return `https://drive.google.com/thumbnail?id=${driveFileMatch[1]}&sz=w1200`;
  }
  const driveIdMatch = cleanUrl.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  if (cleanUrl.includes("drive.google.com") && driveIdMatch && driveIdMatch[1]) {
    return `https://drive.google.com/thumbnail?id=${driveIdMatch[1]}&sz=w1200`;
  }
  return "";
}

function extractGoogleDriveId(url) {
  if (!url || typeof url !== "string") return "";
  const clean = url.trim();
  const fileMatch = clean.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
  if (fileMatch && fileMatch[1]) return fileMatch[1];
  const idMatch = clean.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  if (idMatch && idMatch[1]) return idMatch[1];
  return "";
}

function parseSelectedPages(pagesStr) {
  if (!pagesStr || typeof pagesStr !== "string") return [1];
  const parts = pagesStr.split(/[,\s]+/);
  const pages = [];
  for (const part of parts) {
    if (!part) continue;
    if (part.includes("-")) {
      const [start, end] = part.split("-").map(n => parseInt(n.trim(), 10));
      if (!isNaN(start) && !isNaN(end) && start <= end) {
        for (let p = Math.max(1, start); p <= Math.min(start + 50, end); p++) {
          if (!pages.includes(p)) pages.push(p);
        }
      }
    } else {
      const p = parseInt(part.trim(), 10);
      if (!isNaN(p) && p > 0 && !pages.includes(p)) {
        pages.push(p);
      }
    }
  }
  return pages.length ? pages : [1];
}

function handleImageError(imgEl) {
  if (!imgEl) return;
  const retry = imgEl.dataset.retry;
  if (retry && imgEl.src !== retry) {
    imgEl.dataset.retry = "";
    imgEl.src = retry;
  } else {
    imgEl.style.display = "none";
  }
}

function updateCourseCoverPreview(val, previewId) {
  const container = document.getElementById(previewId);
  if (!container) return;
  const formatted = formatImageUrl(val);
  if (formatted) {
    container.style.display = "block";
    container.innerHTML = `<img src="${escapeHtml(formatted)}" data-retry="${escapeHtml(getDriveFallbackUrl(val))}" onerror="handleImageError(this)" style="width:100%; height:160px; object-fit:cover; border-radius:10px;" />`;
  } else {
    container.style.display = "none";
    container.innerHTML = "";
  }
}

// Narx maydonlari uchun: faqat raqam qoldiradi va har 3 xonadan keyin bo'shliq qo'yadi (1500000 -> 1 500 000)
function formatPriceInput(el) {
  const digits = el.value.replace(/\D/g, "").slice(0, 12);
  el.value = digits.replace(/\B(?=(\d{3})+(?!\d))/g, " ");
}

function extractPriceDigits(rawValue) {
  return String(rawValue || "").replace(/\D/g, "");
}

function formatPriceDigitsForDisplay(rawValue) {
  const digits = extractPriceDigits(rawValue);
  return digits.replace(/\B(?=(\d{3})+(?!\d))/g, " ");
}

// Fayl nomi kengaytmasiga qarab mos ikonka qaytaradi (resurs kartalarida)
function getResourceIcon(fileName) {
  const ext = String(fileName || "").split(".").pop().toLowerCase();
  const map = {
    rvt: "📐", rfa: "📐", rte: "📐",
    pdf: "📄",
    dwg: "📐", dxf: "📐",
    zip: "📦", rar: "📦", "7z": "📦",
    xlsx: "📊", xls: "📊", csv: "📊",
    doc: "📃", docx: "📃",
    jpg: "🖼️", jpeg: "🖼️", png: "🖼️"
  };
  return map[ext] || "📁";
}

// ======================================================
// THEME HANDLING (Apple Dark / Light)
// ======================================================

let currentTheme = localStorage.getItem("theme") || "dark";

function applyTheme(theme) {
  document.documentElement.classList.toggle("light", theme === "light");
  // Telegram sarlavhasi va pastki paneli ilova foniga mos bo'lsin (Bot API 6.1+ / 7.10+)
  try {
    const bg = theme === "light" ? "#f5f5f7" : "#0a0a0a";
    const W = window.Telegram && window.Telegram.WebApp;
    if (W && typeof W.isVersionAtLeast === "function") {
      if (W.isVersionAtLeast("6.1")) { W.setHeaderColor(bg); W.setBackgroundColor(bg); }
      if (W.isVersionAtLeast("7.10") && typeof W.setBottomBarColor === "function") W.setBottomBarColor(bg);
    }
  } catch (e) {}
}

applyTheme(currentTheme);

function toggleTheme() {
  currentTheme = currentTheme === "dark" ? "light" : "dark";
  localStorage.setItem("theme", currentTheme);
  applyTheme(currentTheme);
  haptic("light");
  render();
}

// ======================================================
// HAPTIC FEEDBACK & NOTIFICATIONS
// ======================================================

function haptic(style = "light") {
  try {
    tg.HapticFeedback?.impactOccurred(style);
  } catch (e) {}
}

function showAlert(message) {
  try {
    tg.showAlert(String(message || ""));
  } catch (e) {
    alert(String(message || ""));
  }
}

function showToast(message, duration = 2800) {
  const existing = document.querySelector(".toast");
  if (existing) existing.remove();

  const toast = document.createElement("div");
  toast.className = "toast";
  toast.innerHTML = `<span>🔔</span> ${escapeHtml(message)}`;
  document.body.appendChild(toast);

  setTimeout(() => {
    toast.style.opacity = "0";
    toast.style.transform = "translate(-50%, -20px)";
    toast.style.transition = "all 0.25s ease";
    setTimeout(() => toast.remove(), 260);
  }, duration);
}

function showConfirm(title, message, confirmLabel, onConfirm) {
  if (typeof message === "function") {
    onConfirm = message;
    confirmLabel = "Tasdiqlash";
    message = "";
  } else if (typeof confirmLabel === "function") {
    onConfirm = confirmLabel;
    confirmLabel = "Tasdiqlash";
  }
  if (!confirmLabel) confirmLabel = "Tasdiqlash";

  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  overlay.innerHTML = `
    <div class="modal-card">
      <div class="modal-title">${escapeHtml(title || "Tasdiqlash")}</div>
      ${message ? `<div class="modal-msg">${escapeHtml(message)}</div>` : ""}
      <div class="modal-actions">
        <button type="button" class="modal-btn cancel">Bekor qilish</button>
        <button type="button" class="modal-btn confirm">${escapeHtml(confirmLabel)}</button>
      </div>
    </div>
  `;

  document.body.appendChild(overlay);

  const closeOverlay = () => {
    overlay.classList.add("closing");
    setTimeout(() => overlay.remove(), 180);
  };

  overlay.querySelector(".cancel")?.addEventListener("click", () => {
    haptic();
    closeOverlay();
  });

  overlay.querySelector(".confirm")?.addEventListener("click", async (e) => {
    haptic("medium");
    const confirmBtn = e.currentTarget;
    if (confirmBtn) {
      confirmBtn.disabled = true;
      confirmBtn.style.opacity = "0.6";
    }
    if (typeof onConfirm === "function") {
      try {
        await onConfirm();
        closeOverlay();
      } catch (error) {
        if (confirmBtn) {
          confirmBtn.disabled = false;
          confirmBtn.style.opacity = "1";
        }
        console.error("CONFIRM ERROR:", error);
        showAlert(error.message || "Amalni bajarishda xatolik yuz berdi.");
      }
    } else {
      closeOverlay();
    }
  });
}

// showConfirm HTML-formani escape qilib yuborgani uchun (matn sifatida chiqib
// qolgani) forma elementlari bo'lgan modallar uchun alohida, escape qilmaydigan
// funksiya: bodyHtml xom HTML sifatida ko'rsatiladi, faqat title escape qilinadi.
function showFormModal(title, bodyHtml, confirmLabel, onConfirm) {
  if (!confirmLabel) confirmLabel = "Saqlash";

  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  overlay.innerHTML = `
    <div class="modal-card">
      <div class="modal-title">${escapeHtml(title || "")}</div>
      <div class="modal-msg">${bodyHtml || ""}</div>
      <div class="modal-actions">
        <button type="button" class="modal-btn cancel">Bekor qilish</button>
        <button type="button" class="modal-btn confirm">${escapeHtml(confirmLabel)}</button>
      </div>
    </div>
  `;

  document.body.appendChild(overlay);

  const closeOverlay = () => {
    overlay.classList.add("closing");
    setTimeout(() => overlay.remove(), 180);
  };

  overlay.querySelector(".cancel")?.addEventListener("click", () => {
    haptic();
    closeOverlay();
  });

  overlay.querySelector(".confirm")?.addEventListener("click", async (e) => {
    haptic("medium");
    const confirmBtn = e.currentTarget;
    if (confirmBtn) {
      confirmBtn.disabled = true;
      confirmBtn.style.opacity = "0.6";
    }
    if (typeof onConfirm === "function") {
      try {
        await onConfirm();
        closeOverlay();
      } catch (error) {
        if (confirmBtn) {
          confirmBtn.disabled = false;
          confirmBtn.style.opacity = "1";
        }
        console.error("FORM MODAL ERROR:", error);
        showAlert(error.message || "Amalni bajarishda xatolik yuz berdi.");
      }
    } else {
      closeOverlay();
    }
  });

  return overlay;
}

