function setSpecDevice(device) {
  haptic("light");
  specDevice = device;
  const block = document.getElementById("pc-specs-wrapper");
  if (block) {
    block.outerHTML = renderPcSpecsBlock();
  } else {
    render();
  }
}

function setSpecLevel(level) {
  haptic("light");
  specLevel = level;
  const block = document.getElementById("pc-specs-wrapper");
  if (block) {
    block.outerHTML = renderPcSpecsBlock();
  } else {
    render();
  }
}

