async function submitUpdateCourse(id) {
  const title = document.getElementById("ec-title")?.value.trim();
  const sub = document.getElementById("ec-sub")?.value.trim();
  const priceDigits = document.getElementById("ec-price")?.value.trim();
  const discountPriceDigits = document.getElementById("ec-discount-price")?.value.trim();
  const discountUntil = document.getElementById("ec-discount-until")?.value;
  const category = Array.from(document.querySelectorAll('input[name="ec-category-cb"]:checked')).map(el => el.value);
  const mod = document.getElementById("ec-mod")?.value;
  const less = document.getElementById("ec-less")?.value;
  const rel = document.getElementById("ec-rel")?.value.trim();
  const cover = formatImageUrl(document.getElementById("ec-cover")?.value.trim() || "");
  const status = document.getElementById("ec-status")?.value || "draft";

  if (!title) return showAlert("Kurs nomi majburiy!");

  const price = priceDigits ? `${priceDigits} so'm` : "";
  const discountPrice = discountPriceDigits ? `${discountPriceDigits} so'm` : "";

  try {
    haptic("medium");
    await adminApi(`/api/admin/courses/${Number(id)}/update`, {
      title,
      subtitle: sub,
      price,
      discount_price: discountPrice || null,
      discount_until: discountUntil || null,
      categories: category,
      total_modules: Number(mod) || 0,
      total_lessons: Number(less) || 0,
      release_date: rel,
      cover_url: cover,
      status: status
    });
    showToast("Kurs muvaffaqiyatli yangilandi!");
    closeDetail();
    loadContent();
  } catch (err) {
    showAlert(err.message || "Kursni yangilashda xato.");
  }
}

function deleteCourseModal(id) {
  showConfirm("Kurs o'chirilsinmi?", "Ushbu kurs kartasi o'chiriladi.", "O'chirish", async () => {
    await adminApi(`/api/admin/courses/${Number(id)}/delete`);
    showToast("Kurs o'chirildi!");
    loadContent();
  });
}

// ======================================================
// COURSE PUBLICATION STATUS CONTROLS
// ======================================================

async function setCourseStatus(courseId, newStatus) {
  haptic("medium");
  const toggles = [
    document.getElementById(`course-status-toggle-${courseId}`),
    document.getElementById(`course-status-toggle-btm-${courseId}`)
  ].filter(Boolean);
  toggles.forEach(t => t.setAttribute("data-status", newStatus));

  let bClass = 'draft';
  let bText = '🔒 Qoralama';
  let bHint = "Ushbu kurs hozircha o‘quvchilarga ko‘rinmaydi (Qoralama).";
  let cardClass = 'draft-mode';

  if (newStatus === 'published' || newStatus === 'active') {
    bClass = 'active';
    bText = '🚀 Ommaga chiqarilgan (Sotuvda)';
    bHint = "Ushbu kurs barcha o‘quvchilarga ko‘rinmoqda, preview va darslar ro‘yxati ochiq va sotuvga chiqarilgan.";
    cardClass = 'active-mode';
  } else if (newStatus === 'in_progress') {
    bClass = 'in_progress';
    bText = '🟡 Jarayonda (Tayyorlanmoqda)';
    bHint = "Ushbu kurs o‘quvchilarga faqat karta sifatida ko‘rinadi, lekin ichiga kirish yopiq («Ushbu kurs hozir tayyorlanmoqda»).";
    cardClass = 'in-progress-mode';
  }

  const badges = [
    document.getElementById(`course-status-badge-${courseId}`),
    document.getElementById(`course-status-badge-btm-${courseId}`)
  ].filter(Boolean);
  badges.forEach(b => {
    b.className = `course-status-badge ${bClass}`;
    b.innerHTML = bText;
  });

  const cardEl = document.getElementById(`course-status-card-${courseId}`);
  if (cardEl) {
    cardEl.className = `course-status-card ${cardClass}`;
  }
  const hintEl = document.getElementById(`course-status-hint-${courseId}`);
  if (hintEl) {
    hintEl.textContent = bHint;
  }

  try {
    const res = await adminApi(`/api/admin/courses/${Number(courseId)}/status`, { status: newStatus });
    if (res && res.course) {
      if (courseModulesData && courseModulesData.course && Number(courseModulesData.course.id) === Number(courseId)) {
        courseModulesData.course.status = newStatus;
      }
      const existingInState = (state.courses || []).find(c => Number(c.id) === Number(courseId));
      if (existingInState) {
        existingInState.status = newStatus;
      }
    }
    if (newStatus === "active") {
      showToast("🚀 Kurs muvaffaqiyatli sotuvga chiqarildi!");
    } else {
      showToast("🔒 Kurs qoralamaga olindi (o'quvchilarga ko'rinmaydi).");
    }
  } catch (err) {
    showAlert(err.message || "Kurs holatini o'zgartirishda xato yuz berdi.");
    render();
  }
}

function handleCourseStatusClick(e, courseId) {
  const rect = e.currentTarget.getBoundingClientRect();
  const clickX = e.clientX - rect.left;
  const newStatus = clickX > rect.width / 2 ? "active" : "draft";
  setCourseStatus(courseId, newStatus);
}

function setFormStatus(status, inputId, toggleId, badgeId) {
  haptic("light");
  const input = document.getElementById(inputId);
  if (input) input.value = status;
  const toggle = document.getElementById(toggleId);
  if (toggle) toggle.setAttribute("data-status", status);
  const badge = document.getElementById(badgeId);
  if (badge) {
    let bClass = 'draft';
    let bText = '🔒 Qoralama';
    if (status === 'published' || status === 'active') {
      bClass = 'active';
      bText = '🚀 Ommaga chiqarish (Sotuvda)';
    } else if (status === 'in_progress') {
      bClass = 'in_progress';
      bText = '🟡 Jarayonda (Tayyorlanmoqda)';
    }
    badge.className = `course-status-badge ${bClass}`;
    badge.innerHTML = bText;
  }
}

function handleFormStatusClick(e, inputId, toggleId, badgeId) {
  const rect = e.currentTarget.getBoundingClientRect();
  const clickX = e.clientX - rect.left;
  const newStatus = clickX > rect.width / 2 ? "active" : "draft";
  setFormStatus(newStatus, inputId, toggleId, badgeId);
}

function goToCourseManagement() {
  haptic("light");
  selectedCourseId = null;
  courseModulesData = null;
  activeTab = "lessons";
  currentView = null;
  render();
}

async function openCourseCatalog(courseId) {
  haptic("light");
  const _checkCourse = (state.courses || []).find(c => Number(c.id) === Number(courseId));
  if (_checkCourse && !state.is_admin) {
    if (_checkCourse.status === 'in_progress') {
      showToast("⏳ Ushbu kurs hozir tayyorlanmoqda.");
      return;
    }
    if (_checkCourse.status === 'draft') {
      showToast("🔒 Ushbu kurs hozircha yopiq.");
      return;
    }
  }
  if (Number(courseId) !== Number(selectedCourseId)) {
    expandedModuleIds = new Set();
  }
  selectedCourseId = Number(courseId);
  activeTab = "lessons";
  currentView = {
    html: `
      <div class="page">
        <div class="back-btn" onclick="backToCoursesList()">← Kurslar katalogiga qaytish</div>
        <div class="loading-state" style="padding:60px 0; text-align:center;">
          <div class="spinner"></div>
          <div>Modullar yuklanmoqda...</div>
        </div>
      </div>
    `
  };
  render();

  try {
    const data = await api(`/api/course/${Number(courseId)}/modules`);
    courseModulesData = data;
    currentView = null;
    render();
  } catch (error) {
    showAlert(error.message || "Kurs modullarini yuklashda xatolik.");
    backToCoursesList();
  }
}

function backToCoursesList() {
  haptic("light");
  selectedCourseId = null;
  courseModulesData = null;
  expandedModuleIds = new Set();
  currentView = null;
  render();
}

async function reloadCourseModules() {
  if (!selectedCourseId) return;
  try {
    const data = await api(`/api/course/${Number(selectedCourseId)}/modules`);
    courseModulesData = data;
    render();
  } catch (error) {
    showAlert(error.message || "Yangilashda xatolik.");
  }
}

function renderCourseModules() {
  if (!courseModulesData) {
    return `<div class="page"><div class="loading-state" style="padding:60px 0; text-align:center;"><div class="spinner"></div></div></div>`;
  }

  const course = courseModulesData.course || {};
  const modules = Array.isArray(courseModulesData.modules) ? courseModulesData.modules : [];

  let html = `
    <div class="page">
      <div class="back-btn" onclick="backToCoursesList()">← Kurslar katalogiga qaytish</div>
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px; gap:10px;">
        <div class="page-title" style="margin-bottom:0;">${escapeHtml(course.title || "Kurs")}</div>
      </div>
      <p style="color:var(--text-secondary); font-size:13px; margin-bottom:14px;">
        ${modules.length} ta modul · Kerakli modulni tanlang va darslarni boshlang:
      </p>

      ${(() => {
        const isFree = isCourseFreeCheck(course);
        const hasAccess = Boolean(courseModulesData.has_access || state.has_access || state.is_admin || isFree);
        const daysLeft = courseModulesData.days_left !== undefined ? courseModulesData.days_left : (course.days_left !== undefined ? course.days_left : (state.days_left || 0));
        const expDate = courseModulesData.course?.access_expires_at || state.access_expires_at || state.access_until;
        const accState = courseModulesData.access_state || state.access_state || (hasAccess ? 'ACTIVE' : 'NO_ACCESS');

        if (hasAccess && !isFree) {
          return `
            <div style="background:linear-gradient(135deg, rgba(0,200,83,0.12), rgba(41,121,255,0.06)); border:1.5px solid #00c853; border-radius:var(--radius-md); padding:14px 16px; margin-bottom:18px;">
              <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px;">
                <div style="display:flex; align-items:center; gap:10px;">
                  <span style="font-size:22px;">🟢</span>
                  <div>
                    <div style="font-weight:750; font-size:14px; color:var(--text-primary);">Sizda kursga to'liq a'zolik faol</div>
                    <div style="font-size:12px; color:var(--text-secondary);">
                      ${state.is_admin ? "👑 Bosh administrator (Cheksiz kirish)" : `Qolgan vaqt: <b style="color:var(--text-primary);">${daysLeft} kun</b>${expDate ? ` (${fmtDate(expDate)} gacha)` : ''}`}
                    </div>
                  </div>
                </div>
                <span class="tag" style="background:rgba(0,200,83,0.2); color:#00e676; border:1px solid #00c853;">${state.is_admin ? '👑 Admin' : 'Faol Obuna'}</span>
              </div>
            </div>
          `;
        }

        if (!hasAccess) {
          if (accState === 'EXPIRED') {
            return `
              <div style="background:linear-gradient(135deg, rgba(235,59,59,0.12), rgba(255,149,0,0.08)); border:1.5px solid #eb3b3b; border-radius:var(--radius-md); padding:16px; margin-bottom:18px;">
                <div style="display:flex; align-items:center; gap:10px; margin-bottom:8px;">
                  <span style="font-size:24px;">🔴</span>
                  <div>
                    <div style="font-weight:800; font-size:15px; color:#ff5252;">Kursga kirish muddati tugagan</div>
                    <div style="font-size:12px; color:var(--text-secondary);">Darslarni ko'rishni davom ettirish uchun a'zolik muddatini uzaytiring.</div>
                  </div>
                </div>
                <div style="display:flex; justify-content:space-between; align-items:center; margin-top:12px; padding-top:12px; border-top:1px solid rgba(255,255,255,0.1);">
                  <div style="font-size:13px; color:var(--text-secondary);">
                    Tugagan sana: <b>${fmtDate(expDate) || '-'}</b>
                  </div>
                  <button class="btn" style="width:auto; margin:0; padding:8px 18px; font-size:13px; background:linear-gradient(135deg, #00c853, #009624);" onclick="openCourseAccessModal(${Number(course.id)})">
                    💳 A'zolikni yangilash
                  </button>
                </div>
              </div>
            `;
          }

          if (accState === 'REVOKED') {
            return `
              <div style="background:linear-gradient(135deg, rgba(235,59,59,0.12), rgba(255,59,48,0.08)); border:1.5px solid #eb3b3b; border-radius:var(--radius-md); padding:16px; margin-bottom:18px;">
                <div style="display:flex; align-items:center; gap:10px; margin-bottom:8px;">
                  <span style="font-size:24px;">🚫</span>
                  <div>
                    <div style="font-weight:800; font-size:15px; color:#ff5252;">Kirish huquqi bekor qilingan</div>
                    <div style="font-size:12px; color:var(--text-secondary);">Kursga kirish huquqi administrator tomonidan to'xtatilgan.</div>
                  </div>
                </div>
                <div style="margin-top:10px;">
                  <button class="btn secondary" style="margin:0; padding:8px 18px; font-size:13px;" onclick="openContactAdminDirect()">
                    💬 Administratorga murojaat qilish
                  </button>
                </div>
              </div>
            `;
          }

          return `
            <div style="background:linear-gradient(135deg, rgba(41,121,255,0.12), rgba(0,230,118,0.08)); border:1.5px solid var(--accent); border-radius:var(--radius-md); padding:16px; margin-bottom:18px;">
              <div style="display:flex; align-items:center; gap:10px; margin-bottom:8px;">
                <span style="font-size:24px;">🔒</span>
                <div>
                  <div style="font-weight:800; font-size:15px; color:var(--text-primary);">Ushbu kurs to'liq pullik (PRO) hisoblanadi</div>
                  <div style="font-size:12px; color:var(--text-secondary);">1 yillik to'liq kirish (365 kun), 11 ta modul, 140 ta darslik va amaliy materiallar.</div>
                </div>
              </div>
              <div style="font-size:12px; color:var(--accent); margin-bottom:8px; padding:6px 10px; background:rgba(41,121,255,0.1); border-radius:6px;">
                💡 1-moduldagi namuna darslarni hoziroq bepul ko'rishingiz mumkin!
              </div>
              <div style="display:flex; justify-content:space-between; align-items:center; margin-top:12px; padding-top:12px; border-top:1px solid rgba(255,255,255,0.1);">
                <div style="font-size:15px; font-weight:800; color:var(--accent);">
                  ${escapeHtml(formatCoursePrice(course.discount_price || course.price || "1 500 000 so'm"))}
                </div>
                <button class="btn" style="width:auto; margin:0; padding:8px 18px; font-size:13px; background:linear-gradient(135deg, #00c853, #009624);" onclick="openCourseAccessModal(${Number(course.id)})">
                  💳 Darsga a'zo bo'lish
                </button>
              </div>
            </div>
          `;
        }
        return "";
      })()}

      ${state.is_admin ? `
        <div id="course-status-card-${course.id}" class="course-status-card ${course.status === 'published' || course.status === 'active' ? 'active-mode' : (course.status === 'in_progress' ? 'in-progress-mode' : 'draft-mode')}">
          <div class="course-status-header">
            <div class="course-status-title">
              <span>📡 Kurs Ko'rinishi (Status)</span>
            </div>
            <div id="course-status-badge-${course.id}" class="course-status-badge ${course.status === 'published' || course.status === 'active' ? 'active' : (course.status === 'in_progress' ? 'in_progress' : 'draft')}">
              ${course.status === 'published' || course.status === 'active' ? '🚀 Ommaga chiqarilgan (Sotuvda)' : (course.status === 'in_progress' ? '🟡 Jarayonda (Tayyorlanmoqda)' : '🔒 Qoralama (Yopiq)')}
            </div>
          </div>
          <div id="course-status-hint-${course.id}" class="course-status-hint">
            ${course.status === 'published' || course.status === 'active'
              ? "Ushbu kurs barcha o‘quvchilarga ko‘rinmoqda, preview va darslar ro‘yxati ochiq va sotuvga chiqarilgan."
              : (course.status === 'in_progress'
                  ? "Ushbu kurs o‘quvchilarga faqat karta sifatida ko‘rinadi, lekin ichiga kirish yopiq («Ushbu kurs hozir tayyorlanmoqda»)."
                  : "Ushbu kurs hozircha o‘quvchilarga ko‘rinmaydi (Qoralama).")}
          </div>
          <div class="status-slide-toggle-3" id="course-status-toggle-${course.id}" data-status="${course.status || 'draft'}">
            <div class="status-slide-pill"></div>
            <button type="button" class="status-slide-opt" data-val="draft" onclick="event.stopPropagation(); setCourseStatus(${Number(course.id)}, 'draft')">
              <span class="status-slide-opt-title">🔒 Qoralama</span>
              <span class="status-slide-opt-desc">Yopiq</span>
            </button>
            <button type="button" class="status-slide-opt" data-val="in_progress" onclick="event.stopPropagation(); setCourseStatus(${Number(course.id)}, 'in_progress')">
              <span class="status-slide-opt-title">🟡 Jarayonda</span>
              <span class="status-slide-opt-desc">Karta ochiq</span>
            </button>
            <button type="button" class="status-slide-opt" data-val="published" onclick="event.stopPropagation(); setCourseStatus(${Number(course.id)}, 'published')">
              <span class="status-slide-opt-title">🚀 Ommaga</span>
              <span class="status-slide-opt-desc">Sotuvda</span>
            </button>
          </div>
        </div>

        <button class="admin-small-btn" style="margin-bottom:16px;" onclick="openAddModuleModal(${Number(course.id)})">
          ➕ Yangi Modul Qo'shish
        </button>
      ` : ""}
  `;

  if (!modules.length) {
    html += `<div class="empty-box">Hozircha modullar mavjud emas.</div>`;
  } else {
    modules.forEach((mod, idx) => {
      const lessons = Array.isArray(mod.lessons) ? mod.lessons : [];
      const watched = lessons.filter(l => l.watched).length;

      html += `
        <div class="module ${mod.unlocked ? "" : "locked"}">
          <div class="module-head" onclick="toggleModule(${Number(mod.id)})">
            <div class="module-head-left">
              <span class="idx">${String(idx + 1).padStart(2, "0")}</span>
              <div>
                <div>${escapeHtml(mod.title)}</div>
                <div style="font-size: 11.5px; color: var(--text-secondary); font-weight: 500; margin-top: 2px;">
                  ${watched}/${lessons.length} dars bajarildi
                </div>
              </div>
            </div>
            <div style="display:flex; align-items:center; gap:8px;">
              ${state.is_admin ? `
                <button class="admin-small-btn" style="padding:4px 8px; font-size:11px;" onclick="event.stopPropagation(); openEditModuleModal(${Number(mod.id)})">✏️</button>
                <button class="admin-small-btn" style="padding:4px 8px; font-size:11px; background:rgba(235,59,59,0.8);" onclick="event.stopPropagation(); deleteModuleConfirm(${Number(mod.id)})">🗑️</button>
              ` : ""}
              <div class="tag ${mod.unlocked ? "" : "locked-tag"}">
                ${mod.unlocked ? "Ochiq" : "🔒 Qulflangan"}
              </div>
              <span class="module-chevron">⌄</span>
            </div>
          </div>

          <div class="lesson-list ${expandedModuleIds.has(Number(mod.id)) ? "open" : ""}" id="mod-${Number(mod.id)}">
            ${lessons.length ? lessons.map(lesson => `
              <div class="lesson ${lesson.available ? "" : "disabled"}" onclick="${lesson.available ? `openLesson(${Number(lesson.id)})` : `showLockedInfo(${Number(course.id)})`}">
                <div class="lesson-left">
                  <span class="lesson-status-icon">${lesson.watched ? "✅" : (lesson.available ? "▶" : "🔒")}</span>
                  <span>${escapeHtml(lesson.title)}</span>
                </div>
                <div style="display:flex; align-items:center; gap:8px;">
                  ${lesson.is_free ? `<span class="free-badge">Bepul namuna</span>` : (!lesson.available && !state.is_admin ? `<span class="paid-lesson-chip">🔒 Pullik dars</span>` : "")}
                  ${state.is_admin ? `<button class="admin-small-btn" style="padding:3px 7px; font-size:10.5px;" onclick="event.stopPropagation(); openEditLessonView(${Number(lesson.id)})">✏️</button>` : ""}
                </div>
              </div>
            `).join("") : `<div class="empty-box">Bu modulda darslar hali yuklanmagan.</div>`}

            <div style="padding: 12px 18px; border-top: 1px solid var(--border); display:flex; flex-direction:column; gap:8px;">
              ${state.is_admin ? `
                <button class="btn secondary" style="margin-bottom: 0; padding: 10px;" onclick="event.stopPropagation(); openAddLessonView(${Number(mod.id)})">
                  ➕ Dars Qo'shish
                </button>
              ` : ""}
              ${mod.has_test && (state.has_access || state.is_admin) ? `
                <div style="font-size:12px; color:${mod.test_passed ? "var(--success)" : "var(--text-secondary)"}; text-align:center;">
                  ${mod.test_passed ? "✅ Test topshirilgan — keyingi modul ochiq" : "⚠️ Keyingi modulga o'tish uchun testdan 65%+ ball kerak"}
                </div>
                ${mod.test_passed && mod.retake_available_at ? `
                  <div class="retake-countdown" data-until="${escapeHtml(mod.retake_available_at)}" style="font-size:11px; color:var(--text-secondary); text-align:center;">
                    Hisoblanmoqda...
                  </div>
                ` : ""}
              ` : ""}
              ${mod.has_test ? `
                ${(state.has_access || state.is_admin || courseModulesData.has_access) ? `
                  <button class="btn secondary" style="margin-bottom: 0; padding: 10px;" onclick="event.stopPropagation(); openTest(${Number(mod.id)})">
                    📝 Modul bo'yicha test topshirish
                  </button>
                ` : `
                  <div style="font-size:12px; color:var(--text-secondary); text-align:center; padding:6px 0;">
                    🔒 Testlar faqat kursga kirish huquqi bor o'quvchilar uchun
                  </div>
                `}
              ` : ""}
            </div>
          </div>
        </div>
      `;
    });
  }

  if (!courseModulesData.has_access && !state.has_access && !state.is_admin) {
    html += `
      <div style="margin-top: 18px;">
        <button class="btn" style="background:linear-gradient(135deg, #00c853, #009624);" onclick="openCourseAccessModal(${Number(course.id)})">
          💳 Kursga a'zo bo'lish (To'lov va murojaat)
        </button>
      </div>
    `;
  }

  if (state.is_admin) {
    html += `
      <div class="course-bottom-action-bar">
        <div class="course-status-header">
          <div class="course-status-title">
            <span>⚙️ Pastki boshqaruv: Kursni sotuvga chiqarish</span>
          </div>
          <div id="course-status-badge-btm-${course.id}" class="course-status-badge ${course.status === 'published' || course.status === 'active' ? 'active' : (course.status === 'in_progress' ? 'in_progress' : 'draft')}">
            ${course.status === 'published' || course.status === 'active' ? '🚀 Ommaga chiqarilgan (Sotuvda)' : (course.status === 'in_progress' ? '🟡 Jarayonda' : '🔒 Qoralama (Yopiq)')}
          </div>
        </div>
        <div class="status-slide-toggle-3" id="course-status-toggle-btm-${course.id}" data-status="${course.status || 'draft'}">
          <div class="status-slide-pill"></div>
          <button type="button" class="status-slide-opt" data-val="draft" onclick="event.stopPropagation(); setCourseStatus(${Number(course.id)}, 'draft')">
            <span class="status-slide-opt-title">🔒 Qoralama</span>
            <span class="status-slide-opt-desc">Yopiq</span>
          </button>
          <button type="button" class="status-slide-opt" data-val="in_progress" onclick="event.stopPropagation(); setCourseStatus(${Number(course.id)}, 'in_progress')">
            <span class="status-slide-opt-title">🟡 Jarayonda</span>
            <span class="status-slide-opt-desc">Karta ko'rinadi</span>
          </button>
          <button type="button" class="status-slide-opt" data-val="published" onclick="event.stopPropagation(); setCourseStatus(${Number(course.id)}, 'published')">
            <span class="status-slide-opt-title">🚀 Ommaga chiqarish</span>
            <span class="status-slide-opt-desc">Sotuvda</span>
          </button>
        </div>
      </div>
    `;
  }

  html += `</div>`;
  return html;
}

// ==== MODUL QO'SHISH / TAHRIRLASH / O'CHIRISH ====

function openAddModuleModal(courseId) {
  currentView = {
    html: `
      <div class="page">
        <div class="back-btn" onclick="closeDetail()">← Ortga qaytish</div>
        <div class="page-title">Yangi Modul Qo'shish</div>
        <div class="admin-form">
          <div class="apple-field">
            <label>Modul nomi *</label>
            <input id="new-mod-title" class="apple-input" type="text" placeholder="Masalan: 1-Modul. Revit asoslari">
          </div>
          <div class="apple-field">
            <label>Modul tavsifi (ixtiyoriy)</label>
            <textarea id="new-mod-desc" class="apple-input apple-textarea" placeholder="Qisqacha izoh..."></textarea>
          </div>
          <button class="btn" onclick="submitCreateModule(${Number(courseId)})">
            💾 Modulni saqlash
          </button>
        </div>
      </div>
    `
  };
  render();
}

async function submitCreateModule(courseId) {
  const title = document.getElementById("new-mod-title")?.value.trim();
  const description = document.getElementById("new-mod-desc")?.value.trim();
  if (!title) return showAlert("Modul nomi kiritilishi shart!");

  try {
    haptic("medium");
    await adminApi("/api/admin/modules/add", {
      course_id: Number(courseId),
      title,
      description: description || null
    });
    showToast("Modul muvaffaqiyatli qo'shildi!");
    currentView = null;
    await reloadCourseModules();
  } catch (error) {
    showAlert(error.message || "Modul qo'shishda xatolik.");
  }
}

function openEditModuleModal(moduleId) {
  const modules = (courseModulesData && courseModulesData.modules) || [];
  const mod = modules.find(m => Number(m.id) === Number(moduleId));
  if (!mod) return showAlert("Modul topilmadi.");

  currentView = {
    html: `
      <div class="page">
        <div class="back-btn" onclick="closeDetail()">← Ortga qaytish</div>
        <div class="page-title">Modulni Tahrirlash</div>
        <div class="admin-form">
          <div class="apple-field">
            <label>Modul nomi *</label>
            <input id="edit-mod-title" class="apple-input" type="text" value="${escapeHtml(mod.title)}">
          </div>
          <div class="apple-field">
            <label>Tartib raqami *</label>
            <input id="edit-mod-order" class="apple-input" type="number" value="${Number(mod.order_index || 1)}">
          </div>
          <button class="btn" onclick="submitUpdateModule(${Number(moduleId)})">
            💾 O'zgarishlarni saqlash
          </button>
        </div>
      </div>
    `
  };
  render();
}

async function submitUpdateModule(moduleId) {
  const title = document.getElementById("edit-mod-title")?.value.trim();
  const orderIndex = document.getElementById("edit-mod-order")?.value;
  if (!title) return showAlert("Modul nomi kiritilishi shart!");

  try {
    haptic("medium");
    await adminApi(`/api/admin/modules/${Number(moduleId)}/update`, {
      title,
      order_index: Number(orderIndex)
    });
    showToast("Modul yangilandi!");
    currentView = null;
    await reloadCourseModules();
  } catch (error) {
    showAlert(error.message || "Modulni yangilashda xatolik.");
  }
}

function deleteModuleConfirm(moduleId) {
  showConfirm(
    "Modul o'chirilsinmi?",
    "Ushbu modul va undagi barcha darslar butunlay o'chiriladi.",
    "Ha, o'chirish",
    async () => {
      await adminApi(`/api/admin/modules/${Number(moduleId)}/delete`);
      showToast("Modul o'chirildi!");
      await reloadCourseModules();
    }
  );
}

let expandedModuleIds = new Set();

function toggleModule(id) {
  haptic("light");
  const numId = Number(id);
  if (expandedModuleIds.has(numId)) {
    expandedModuleIds.delete(numId);
  } else {
    expandedModuleIds.add(numId);
  }
  const el = document.getElementById(`mod-${numId}`);
  if (el) el.classList.toggle("open");
}

function showLockedInfo(courseId, isSequentialOnly) {
  haptic("medium");
  const cid = Number(courseId) || Number(selectedCourseId);
  const course = (state.courses || []).find(c => Number(c.id) === cid) || (courseModulesData?.course);
  const isFree = isCourseFreeCheck(course);
  const userHasAccess = Boolean(courseModulesData?.has_access || state.has_access || state.is_admin || isFree);
  const accState = courseModulesData?.access_state || state.access_state || (userHasAccess ? 'ACTIVE' : 'NO_ACCESS');

  if (userHasAccess || isSequentialOnly) {
    showAlert("Ushbu dars hali ochilmagan. Qachonki siz bundan oldingi darslikni to'liq ko'rib bo'lganingizdan keyin ('To'liq ko'rib bo'ldim' tugmasini bosgach), keyingi darslik ochiladi.");
  } else if (accState === 'EXPIRED') {
    showAlert("INTPRO kursiga kirish muddati tugagan. Qayta darslarni ko'rish uchun kurs a'zoligini yangilang.");
    openCourseAccessModal(cid || 1);
  } else if (accState === 'REVOKED') {
    showAlert("Kursga kirish huquqi administrator tomonidan bekor qilingan. Iltimos, administratorga murojaat qiling.");
  } else if (cid) {
    showAlert("Ushbu kurs pullik (PRO) hisoblanadi. Darslarni ko'rish uchun avval to'lov qilishingiz va 1 yillik a'zolikni faollashtirishingiz kerak.");
    openCourseAccessModal(cid);
  } else {
    showAlert("Ushbu dars qulflangan. Kursga to'liq kirish uchun adminga murojaat qiling.");
  }
}

// ======================================================
// LESSON DETAIL
// ======================================================

async function resumeLastLesson() {
  if (!state.last_lesson) return;
  const courseId = state.last_lesson.course_id;
  if (courseId) {
    selectedCourseId = Number(courseId);
    activeTab = "lessons";
    try {
      const data = await api(`/api/course/${Number(courseId)}/modules`);
      courseModulesData = data;
    } catch (error) {
      // sokin xato — baribir darsni ochishga urinamiz
    }
  }
  openLesson(state.last_lesson.lesson_id);
}

async function openLesson(id) {
  try {
    haptic("light");
    trackAnalyticsEvent('lesson_opened', 'lesson', id);
    currentView = {
      html: `
        <div class="lesson-loading">
          <div class="spinner"></div>
          <div>Dars ma'lumotlari yuklanmoqda...</div>
        </div>
      `
    };
    render();

    const lesson = await api(`/api/lesson/${Number(id)}`);

    if (lesson.error === "locked") {
      currentView = null;
      render();
      if (lesson.reason === 'unpaid') { return showLockedInfo(selectedCourseId, false); } else { return showLockedInfo(selectedCourseId, true); }
    }

    const currentCourse = (state.courses || []).find(c => Number(c.id) === Number(selectedCourseId));
    const currentModuleData = courseModulesData && Array.isArray(courseModulesData.modules)
      ? courseModulesData.modules.find(m => (m.lessons || []).some(l => Number(l.id) === Number(lesson.id)))
      : null;

    if (currentModuleData) {
      expandedModuleIds.add(Number(currentModuleData.id));
    }

    state.last_lesson = {
      lesson_id: lesson.id,
      lesson_title: lesson.title,
      module_title: currentModuleData ? currentModuleData.title : (state.last_lesson?.module_title || null),
      course_id: selectedCourseId || state.last_lesson?.course_id || null,
      course_title: currentCourse ? currentCourse.title : (state.last_lesson?.course_title || null)
    };

    setActivityWatchingLesson(lesson, currentModuleData, currentCourse);

    const watermarkText = `${state.first_name || ""} · ID ${escapeHtml(String(state.telegram_id || ""))}`.trim();
    const watermarkHtml = `
      <div class="video-watermark">
        <span>${watermarkText}</span>
        <span>${watermarkText}</span>
      </div>
    `;

    function getClientYouTubeEmbed(url) {
      if (!url || typeof url !== "string") return null;
      var clean = url.trim();
      var srcMatch = clean.match(/src=["']([^"']+)["']/i);
      if (srcMatch && srcMatch[1]) clean = srcMatch[1];
      let videoId = null;
      if (/^[a-zA-Z0-9_-]{11}$/.test(clean)) {
        videoId = clean;
      } else {
        var m = clean.match(/(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?|live|shorts)\/|.*[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/i);
        if (m && m[1]) videoId = m[1];
      }
      if (videoId) {
        return `https://www.youtube-nocookie.com/embed/${videoId}?modestbranding=1&rel=0&playsinline=1&controls=1&iv_load_policy=3&showinfo=0&disablekb=1`;
      }
      return null;
    }

    const ytEmbed = lesson.youtube_player_url ||
      getClientYouTubeEmbed(lesson.youtube_url) ||
      getClientYouTubeEmbed(lesson.bunny_player_url) ||
      getClientYouTubeEmbed(lesson.bunny_video_id);

    let videoHtml = "";
    const isTelegramStream = lesson.video_type === 'telegram' || Boolean(lesson.stream_url);
    const tgStreamSrc = lesson.stream_url || (lesson.video_type === 'telegram' ? lesson.video_url : null);

    if (isTelegramStream && tgStreamSrc) {
      const fbYt = ytEmbed || '';
      const fbBunny = (lesson.bunny_player_url && !lesson.bunny_player_url.includes(tgStreamSrc)) ? lesson.bunny_player_url : '';
      videoHtml = `
        <div class="video-container" style="background:#000; display:flex; align-items:center; justify-content:center;" data-yt-fallback="${escapeHtml(fbYt)}" data-bunny-fallback="${escapeHtml(fbBunny)}">
          <video controls playsinline controlslist="nodownload" preload="metadata" style="width:100%; max-height:420px; border-radius:12px;" onerror="handleTgStreamFallback(this)">
            <source src="${escapeHtml(tgStreamSrc)}" type="video/mp4" onerror="handleTgStreamFallback(this.parentElement)">
            Brauzeringiz videoni qo'llab-quvvatlamaydi.
          </video>
          ${watermarkHtml}
        </div>
      `;
    } else if (ytEmbed) {
      videoHtml = `
        <div class="video-container">
          <iframe src="${escapeHtml(ytEmbed)}" title="${escapeHtml(lesson.title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>
          ${watermarkHtml}
        </div>
      `;
    } else if (lesson.bunny_player_url && /\.mp4($|\?)/i.test(lesson.bunny_player_url)) {
      videoHtml = `
        <div class="video-container" style="background:#000; display:flex; align-items:center; justify-content:center;">
          <video controls playsinline controlslist="nodownload" preload="metadata" style="width:100%; max-height:420px; border-radius:12px;">
            <source src="${escapeHtml(lesson.bunny_player_url)}" type="video/mp4">
            Brauzeringiz videoni qo'llab-quvvatlamaydi.
          </video>
          ${watermarkHtml}
        </div>
      `;
    } else if (lesson.bunny_player_url) {
      videoHtml = `
        <div class="video-container">
          <iframe src="${escapeHtml(lesson.bunny_player_url)}" title="${escapeHtml(lesson.title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>
          ${watermarkHtml}
        </div>
      `;
    } else if (lesson.files && lesson.files.length > 0 && lesson.files.some(f => /youtube|youtu\.be|mediadelivery|bunny|drive\.google|\.mp4/i.test(f.file_url || ''))) {
      const vidFile = lesson.files.find(f => /youtube|youtu\.be|mediadelivery|bunny|drive\.google|\.mp4/i.test(f.file_url || ''));
      const embedFromFile = getClientYouTubeEmbed(vidFile.file_url);
      if (embedFromFile) {
        videoHtml = `
          <div class="video-container">
            <iframe src="${escapeHtml(embedFromFile)}" title="${escapeHtml(lesson.title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>
            ${watermarkHtml}
          </div>
        `;
      } else {
        videoHtml = `
          <div class="video-container">
            <iframe src="${escapeHtml(vidFile.file_url)}" title="${escapeHtml(lesson.title)}" allowfullscreen></iframe>
            ${watermarkHtml}
          </div>
        `;
      }
    } else {
      videoHtml = `
        <div class="lesson-no-video">
          🎬 Ushbu dars uchun video hozircha joylashtirilmagan.
        </div>
      `;
    }

    currentView = {
      html: `
        <div class="lesson-detail">
          <div class="back-btn" onclick="closeDetail()">← Darslar ro'yxatiga qaytish</div>
          ${videoHtml}

          <div class="lesson-detail-body">
            <h2 class="lesson-detail-title">${escapeHtml(lesson.title)}</h2>

            ${lesson.task_text ? `
              <div class="task-box">
                <div class="task-box-title">📋 Dars Vazifasi</div>
                <div class="task-box-content">${escapeHtml(lesson.task_text).replace(/\n/g, "<br>")}</div>
              </div>
              ${renderPracticeBox(lesson.id, lesson.my_submission)}
            ` : ""}

            ${renderLessonFiles(lesson.files)}
            ${renderLessonWarning(lesson.warning_text)}
            ${renderLessonQABox(lesson.id, lesson.questions)}

            <button class="btn" style="margin-top: 18px; ${lesson.watched ? 'opacity:0.6;' : ''}" onclick="${lesson.watched ? '' : `markLessonWatched(${Number(lesson.id)})`}">
              ${lesson.watched ? "✅ To'liq ko'rib bo'ldim (Tugallangan)" : "✅ To'liq ko'rib bo'ldim (Keyingi darsni ochish)"}
            </button>

            ${renderLessonNavButtons(lesson.id)}

            <button class="btn secondary" style="margin-top: 10px;" onclick="openLessonDrawer(${Number(lesson.id)})">
              📚 Darslar ro'yxati
            </button>

            <button class="btn secondary" style="margin-top: 10px;" onclick="closeDetail()">
              ← Barcha darslarga qaytish
            </button>
          </div>
        </div>
      `
    };
    render();
    window.scrollTo(0, 0);
  } catch (error) {
    console.error("OPEN LESSON ERROR:", error);
    currentView = null;
    render();
    showAlert(error.message || "Darsni ochishda xatolik yuz berdi.");
  }
}

const PRACTICE_STATUS_META = {
  submitted: { label: "🕓 Tekshirilmoqda", cls: "" },
  approved: { label: "✅ Qabul qilindi", cls: "passed" },
  needs_revision: { label: "🔁 Qayta ishlash kerak", cls: "locked-tag" }
};

function renderPracticeBox(lessonId, submission) {
  if (!submission) {
    return `
      <div class="task-box" style="margin-top:12px;">
        <div class="task-box-title">📤 Vazifani Topshirish</div>
        <div class="apple-field" style="margin-top:10px;">
          <label>Ishingiz linki (Google Drive, Dropbox...) *</label>
          <input id="practice-url-${Number(lessonId)}" class="apple-input" type="url" placeholder="https://drive.google.com/...">
        </div>
        <div class="apple-field">
          <label>Izoh (ixtiyoriy)</label>
          <textarea id="practice-comment-${Number(lessonId)}" class="apple-input apple-textarea" placeholder="Qo'shimcha izoh..."></textarea>
        </div>
        <button class="btn secondary" style="margin-bottom:0;" onclick="submitPractice(${Number(lessonId)})">
          📤 Vazifani yuborish
        </button>
      </div>
    `;
  }

  const meta = PRACTICE_STATUS_META[submission.status] || PRACTICE_STATUS_META.submitted;
  const canResubmit = submission.status !== "approved";

  return `
    <div class="task-box" style="margin-top:12px;">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;">
        <div class="task-box-title" style="margin:0;">📤 Sizning Topshiriqingiz</div>
        <div class="tag ${meta.cls}">${meta.label}</div>
      </div>
      <div style="font-size:13.5px; margin-bottom:6px;">
        🔗 <a href="${escapeHtml(submission.submission_url)}" target="_blank" rel="noopener noreferrer" style="color:var(--accent);">${escapeHtml(submission.submission_url)}</a>
      </div>
      ${submission.comment ? `<div style="font-size:13px; color:var(--text-secondary); margin-bottom:6px;">💬 ${escapeHtml(submission.comment)}</div>` : ""}
      ${submission.admin_comment ? `<div style="font-size:13px; color:var(--accent); margin-top:8px; padding-top:8px; border-top:1px solid var(--border);">👨‍🏫 Admin izohi: ${escapeHtml(submission.admin_comment)}</div>` : ""}

      ${canResubmit ? `
        <div style="margin-top:14px; padding-top:14px; border-top:1px solid var(--border);">
          <div class="apple-field">
            <label>Qayta topshirish (yangi link)</label>
            <input id="practice-url-${Number(lessonId)}" class="apple-input" type="url" placeholder="https://drive.google.com/...">
          </div>
          <div class="apple-field">
            <label>Izoh (ixtiyoriy)</label>
            <textarea id="practice-comment-${Number(lessonId)}" class="apple-input apple-textarea" placeholder="Qo'shimcha izoh..."></textarea>
          </div>
          <button class="btn secondary" style="margin-bottom:0;" onclick="submitPractice(${Number(lessonId)})">
            🔁 Qayta yuborish
          </button>
        </div>
      ` : ""}
    </div>
  `;
}

async function submitPractice(lessonId) {
  const urlInput = document.getElementById(`practice-url-${Number(lessonId)}`);
  const commentInput = document.getElementById(`practice-comment-${Number(lessonId)}`);
  const url = urlInput?.value.trim();
  const comment = commentInput?.value.trim();

  if (!url) return showAlert("Ishingiz linkini kiriting!");

  try {
    haptic("medium");
    await api(`/api/practice/${Number(lessonId)}/submit`, {
      submission_url: url,
      comment: comment || ""
    });
    showToast("Vazifa muvaffaqiyatli yuborildi!");
    openLesson(lessonId);
  } catch (error) {
    showAlert(error.message || "Vazifani yuborishda xatolik.");
  }
}

function renderLessonFiles(files) {
  if (!Array.isArray(files) || !files.length) return "";
  // Video va stream havolalarini yuklab olish bo'limidan chiqarib tashlaymiz
  const downloadableFiles = files.filter(f => {
    const url = (f.file_url || "").toLowerCase();
    return !url.includes("youtube.com") && !url.includes("youtu.be") && !url.includes("mediadelivery.net");
  });
  if (!downloadableFiles.length) return "";
  return `
    <div class="lesson-section">
      <div class="section-title" style="margin-left:0; margin-right:0;">📥 Dars Materiallari</div>
      <div class="files-description">Ushbu darsga biriktirilgan manbalar va ishchi fayllarni yuklab oling:</div>
      <div class="lesson-files">
        ${downloadableFiles.map(f => `
          <div class="lesson-file">
            <div class="lesson-file-info">
              <span class="lesson-file-icon">${getResourceIcon(f.file_name)}</span>
              <span class="lesson-file-name">${escapeHtml(f.file_name || "Material")}</span>
            </div>
            <a class="download-file-btn" href="${escapeHtml(f.file_url)}" target="_blank" rel="noopener noreferrer">
              Yuklab olish 📥
            </a>
          </div>
        `).join("")}
      </div>
    </div>
  `;
}

function renderLessonWarning(warningText) {
  const text = (warningText || "").trim();
  if (!text) return "";
  return `
    <div class="lesson-warning">
      <div class="lesson-warning-title">⚠️ DIQQAT VA OGOHLANTIRISH</div>
      <div class="lesson-warning-text">${escapeHtml(text).replace(/\n/g, "<br>")}</div>
    </div>
  `;
}

function renderLessonQABox(lessonId, questions) {
  const qList = Array.isArray(questions) ? questions : [];

  return `
    <div class="lesson-qa-box" id="lesson-qa-box-${lessonId}">
      <div class="lesson-qa-header">
        <div class="lesson-qa-title">
          <span>💬 Dars Bo'yicha Savol Berish</span>
        </div>
        <span class="tag">${qList.length} ta savol</span>
      </div>
      <div class="lesson-qa-desc">
        Ushbu darsda tushunmagan joyingiz bo‘lsa, savolingizni yozing. Ustoz sizga javob qaytaradi.
      </div>

      ${(state.has_access || state.is_admin) ? `
        <div class="qa-form">
          <textarea
            id="qa-input-${lessonId}"
            class="qa-textarea"
            placeholder="Dars yuzasidan savolingizni aniq yozing..."
          ></textarea>
          <button
            type="button"
            class="qa-submit-btn"
            onclick="submitLessonQuestion(${Number(lessonId)})"
          >
            🚀 Savolni ustozga yuborish
          </button>
        </div>
      ` : `
        <div style="background:var(--bg-surface); border:1px solid var(--border); border-radius:var(--radius-md); padding:14px; text-align:center; margin-bottom:14px;">
          <div style="font-size:20px; margin-bottom:6px;">🔒</div>
          <div style="font-size:13px; font-weight:700; color:var(--text-primary); margin-bottom:4px;">
            Dars bo'yicha savol berish faqat kursga a'zo bo'lgan o'quvchilar uchun ochiq
          </div>
          <div style="font-size:11.5px; color:var(--text-secondary); margin-bottom:12px;">
            Ustozdan to'liq amaliy yordam va savol-javob imkoniyatidan foydalanish uchun kursga a'zo bo'ling.
          </div>
          <button class="btn" style="width:auto; margin:0 auto; padding:8px 18px; font-size:12.5px; background:linear-gradient(135deg, #00c853, #009624);" onclick="openCourseAccessModal(${Number(selectedCourseId || 1)})">
            💳 Kursga a'zo bo'lish
          </button>
        </div>
      `}

      <div class="qa-list" id="qa-list-${lessonId}">
        ${qList.length ? qList.map(q => renderSingleLessonQaCard(q, lessonId)).join("") : `<div style="font-size:12px; color:var(--text-muted); text-align:center; padding:10px 0;">Hozircha savollar yo‘q. Birinchi bo‘lib savol bering!</div>`}
      </div>
    </div>
  `;
}

function renderSingleLessonQaCard(q, lessonId) {
  const isMine = Boolean(q.is_mine);
  const isPublic = Boolean(q.is_public);
  const isAdmin = Boolean(state.is_admin);

  return `
    <div class="qa-card ${q.status === 'answered' ? 'answered' : ''}" id="qa-card-${q.id}">
      <div class="qa-card-head" style="display:flex; justify-content:space-between; align-items:flex-start; gap:8px;">
        <div style="display:flex; flex-direction:column; gap:2px;">
          <span class="qa-author">
            👤 ${escapeHtml([q.first_name, q.last_name].filter(Boolean).join(" ") || "O‘quvchi")}
            ${isMine ? '<span style="font-size:10px; opacity:0.8; color:var(--accent); font-weight:700;">(Siz)</span>' : ''}
          </span>
          <div style="display:flex; align-items:center; gap:6px; margin-top:2px;">
            ${isPublic ? `
              <span class="tag passed" style="font-size:10px; padding:2px 7px; border-radius:10px;">🌐 Ommaviy</span>
            ` : `
              <span class="tag" style="font-size:10px; padding:2px 7px; border-radius:10px; background:rgba(255,170,0,0.15); color:#ffa000;">🔒 Shaxsiy</span>
            `}
            <span class="qa-time">${fmtTimeAgo(q.created_at)}</span>
          </div>
        </div>

        ${isAdmin ? `
          <div style="display:flex; align-items:center; gap:4px;">
            <button class="admin-small-btn" onclick="toggleLessonQuestionVisibility(${Number(q.id)}, ${Number(lessonId)})" title="${isPublic ? 'Shaxsiy qilish' : 'Ommaga ulashish'}" style="font-size:10.5px; padding:3px 7px; ${isPublic ? 'color:#2979ff; border:1px solid rgba(41,121,255,0.3);' : ''}">
              ${isPublic ? '🔒 Shaxsiy' : '🌐 Ommaviy'}
            </button>
            <button class="admin-small-btn" onclick="deleteLessonQuestion(${Number(q.id)}, ${Number(lessonId)})" title="O‘chirish" style="font-size:10.5px; padding:3px 6px; color:#eb3b3b; background:rgba(235,59,59,0.15);">
              🗑️
            </button>
          </div>
        ` : ""}
      </div>

      <div class="qa-question-text" style="margin-top:6px;">${escapeHtml(q.question)}</div>

      ${q.status === 'answered' && q.answer ? `
        <div class="qa-answer-block" style="margin-top:8px;">
          <div class="qa-answer-title">
            <span>👑 Ustoz javobi:</span>
            <span style="font-size:10px; opacity:0.75; font-weight:normal; margin-left:auto;">${fmtTimeAgo(q.answered_at)}</span>
          </div>
          <div class="qa-answer-text">${escapeHtml(q.answer).replace(/\n/g, "<br>")}</div>
        </div>
      ` : `
        <div style="font-size:11.5px; color:var(--warning); display:flex; align-items:center; gap:4px; margin-top:6px;">
          ⏳ Ustoz ko‘rib chiqmoqda...
        </div>
      `}

      ${isAdmin ? `
        <div style="margin-top:10px; border-top:1px dashed var(--border); padding-top:8px;">
          <textarea id="lesson-admin-reply-${q.id}" class="qa-textarea" style="min-height:50px; font-size:12px; margin-bottom:6px;" placeholder="${q.status === 'answered' ? 'Javobni tahrirlash...' : 'Ushbu savolga javob yozish...'}">${escapeHtml(q.answer || '')}</textarea>
          <div style="display:flex; justify-content:space-between; align-items:center;">
            <label style="font-size:11.5px; color:var(--text-secondary); display:inline-flex; align-items:center; gap:4px; cursor:pointer;">
              <input type="checkbox" id="lesson-reply-public-${q.id}" ${isPublic ? 'checked' : ''} style="width:14px; height:14px; accent-color:var(--accent);">
              Ommaga ulashish
            </label>
            <button class="btn" style="width:auto; margin:0; padding:6px 12px; font-size:11.5px;" onclick="submitLessonAdminReply(${Number(q.id)}, ${Number(lessonId)})">
              ${q.status === 'answered' ? 'Javobni yangilash' : 'Javob yuborish'}
            </button>
          </div>
        </div>
      ` : ""}
    </div>
  `;
}

async function toggleLessonQuestionVisibility(questionId, lessonId) {
  try {
    haptic("light");
    const res = await adminApi(`/api/admin/questions/${Number(questionId)}/toggle-public`, {});
    showToast(res.message || "Ko‘rinish o‘zgartirildi!");
    await reloadLessonQuestions(lessonId);
  } catch (err) {
    showAlert(err.message || "Xatolik yuz berdi.");
  }
}

async function deleteLessonQuestion(questionId, lessonId) {
  if (!confirm("Haqiqatan ham ushbu savolni o‘chirmoqchimisiz?")) return;
  try {
    haptic("medium");
    const res = await adminApi(`/api/admin/questions/${Number(questionId)}/delete`, {});
    showToast(res.message || "Savol o‘chirildi!");
    await reloadLessonQuestions(lessonId);
  } catch (err) {
    showAlert(err.message || "O‘chirishda xatolik yuz berdi.");
  }
}

async function submitLessonAdminReply(questionId, lessonId) {
  const input = document.getElementById(`lesson-admin-reply-${questionId}`);
  const isPubCheckbox = document.getElementById(`lesson-reply-public-${questionId}`);
  const answer = input ? input.value.trim() : "";
  if (!answer) return showAlert("Iltimos, javob matnini yozing!");

  try {
    haptic("medium");
    const isPublic = isPubCheckbox ? isPubCheckbox.checked : false;
    const res = await adminApi(`/api/admin/questions/${Number(questionId)}/reply`, { answer, is_public: isPublic });
    showToast(res.message || "Javob yuborildi!");
    await reloadLessonQuestions(lessonId);
  } catch (err) {
    showAlert(err.message || "Xatolik yuz berdi.");
  }
}

async function reloadLessonQuestions(lessonId) {
  try {
    const updatedLesson = await api(`/api/lesson/${Number(lessonId)}`);
    const qaListEl = document.getElementById(`qa-list-${lessonId}`);
    if (qaListEl && updatedLesson && Array.isArray(updatedLesson.questions)) {
      qaListEl.innerHTML = updatedLesson.questions.length
        ? updatedLesson.questions.map(q => renderSingleLessonQaCard(q, lessonId)).join("")
        : `<div style="font-size:12px; color:var(--text-muted); text-align:center; padding:10px 0;">Hozircha savollar yo‘q. Birinchi bo‘lib savol bering!</div>`;
    }
  } catch (e) {}
}

async function submitLessonQuestion(lessonId) {
  if (!state.has_access && !state.is_admin) {
    showAlert("Dars bo'yicha savol berish faqat kursga a'zo bo'lgan (to'lov qilgan) o'quvchilar uchun mavjud.");
    return openCourseAccessModal(selectedCourseId || 1);
  }
  const input = document.getElementById(`qa-input-${lessonId}`);
  const text = input ? input.value.trim() : "";
  if (!text) {
    return showAlert("Iltimos, dars yuzasidan savolingizni yozing!");
  }

  try {
    haptic("medium");
    const res = await api(`/api/lesson/${Number(lessonId)}/question`, { question: text });
    input.value = "";
    showToast(res.message || "Savolingiz ustozga yuborildi!");
    await reloadLessonQuestions(lessonId);
  } catch (err) {
    showAlert(err.message || "Savol yuborishda xatolik yuz berdi.");
  }
}

