// ---- Like / Save (optimistik yangilanish) ----
function _matPatch(id, key, on, delta) {
  const m = (materialsState.allMaterials || []).find(x => Number(x.id) === Number(id));
  if (m) m[key] = Math.max(0, (Number(m[key]) || 0) + delta);
  const setName = key === "like_count" ? "likedIds" : "savedIds";
  if (!(materialsState[setName] instanceof Set)) materialsState[setName] = new Set();
  if (on) materialsState[setName].add(Number(id)); else materialsState[setName].delete(Number(id));
  const attr = key === "like_count" ? "data-mat-like" : "data-mat-save";
  document.querySelectorAll(`[${attr}="${Number(id)}"]`).forEach(el => {
    el.classList.toggle("on", on);
    const c = el.querySelector(".mcat-count");
    if (c && m) c.textContent = (m[key] || 0) > 0 ? m[key] : "";
  });

  // Update header badges
  const likeBadge = document.getElementById("mcat-like-badge");
  if (likeBadge) {
    const lCount = materialsState.likedIds ? materialsState.likedIds.size : 0;
    likeBadge.textContent = lCount > 0 ? lCount : "";
    likeBadge.style.display = lCount > 0 ? "inline-flex" : "none";
  }
  const saveBadge = document.getElementById("mcat-save-badge");
  if (saveBadge) {
    const sCount = materialsState.savedIds ? materialsState.savedIds.size : 0;
    saveBadge.textContent = sCount > 0 ? sCount : "";
    saveBadge.style.display = sCount > 0 ? "inline-flex" : "none";
  }

  // Reactive instant removal if user is currently viewing Liked or Saved tab
  if ((materialsState.currentViewTab === "liked" && key === "like_count" && !on) ||
      (materialsState.currentViewTab === "saved" && key === "save_count" && !on)) {
    updateMaterialsUiInPlace();
  }

  return m;
}

async function toggleMaterialReaction(id, kind) {
  const key = kind === "like" ? "like_count" : "save_count";
  const setName = kind === "like" ? "likedIds" : "savedIds";
  const was = materialsState[setName] instanceof Set && materialsState[setName].has(Number(id));
  haptic(was ? "light" : "medium");
  _matPatch(id, key, !was, was ? -1 : 1);
  try {
    const res = await api(kind === "like" ? "/api/materials/toggle-like" : "/api/materials/toggle-save", { id: Number(id) });
    if (!res || !res.ok) throw new Error("fail");
  } catch (e) {
    _matPatch(id, key, was, was ? 1 : -1);
    showToast("Saqlab bo‘lmadi, qayta urinib ko‘ring");
  }
}

function syncMaterialStatsFromDetail(res) {
  if (!res || !res.stats || !res.material) return;
  const id = Number(res.material.id);
  if (!(materialsState.likedIds instanceof Set)) materialsState.likedIds = new Set();
  if (!(materialsState.savedIds instanceof Set)) materialsState.savedIds = new Set();
  if (res.stats.liked) materialsState.likedIds.add(id); else materialsState.likedIds.delete(id);
  if (res.stats.saved) materialsState.savedIds.add(id); else materialsState.savedIds.delete(id);
  const m = (materialsState.allMaterials || []).find(x => Number(x.id) === id);
  if (m) {
    m.view_count = res.stats.view_count;
    m.like_count = res.stats.like_count;
    m.save_count = res.stats.save_count;
  }
}

function matReactionButtonHtml(id, kind, small) {
  const isLike = kind === "like";
  const set = isLike ? materialsState.likedIds : materialsState.savedIds;
  const on = set instanceof Set && set.has(Number(id));
  const m = (materialsState.allMaterials || []).find(x => Number(x.id) === Number(id));
  const cnt = m ? (isLike ? m.like_count : m.save_count) : 0;
  const icon = isLike
    ? `<svg viewBox="0 0 24 24" width="${small ? 15 : 17}" height="${small ? 15 : 17}" class="mcat-ico"><path d="M12 21s-7.5-4.6-9.6-9.2C1 8.5 2.8 5 6.2 5c2 0 3.3 1 3.8 2.1C10.5 6 11.8 5 13.8 5c3.4 0 5.2 3.5 3.8 6.8C19.5 16.4 12 21 12 21z" transform="translate(1 0)"/></svg>`
    : `<svg viewBox="0 0 24 24" width="${small ? 15 : 17}" height="${small ? 15 : 17}" class="mcat-ico"><path d="M6 3h12a1 1 0 0 1 1 1v17l-7-4.5L5 21V4a1 1 0 0 1 1-1z"/></svg>`;
  return `<button type="button" class="mcat-icon-btn ${on ? "on" : ""}" ${isLike ? "data-mat-like" : "data-mat-save"}="${Number(id)}" aria-label="${isLike ? "Yoqdi" : "Saqlash"}" onclick="event.stopPropagation(); toggleMaterialReaction(${Number(id)}, '${kind}')">${icon}<span class="mcat-count">${cnt > 0 ? cnt : ""}</span></button>`;
}

// ---- Animatsiyali placeholder: harflab yozilib, keyin o‘chib, keyingi so‘zga o‘tadi ----
const MAT_PH_WORDS_I18N = {
  ru: ["Ламинат", "Гипсокартон", "Профиль", "Керамогранит", "Краска", "Плитка", "Двери", "Стекло"],
  uz: ["Laminat", "Gipsokarton", "Profil", "Keramogranit", "Bo‘yoq", "Plitka", "Eshik", "Oyna"],
  en: ["Laminate", "Drywall", "Profile", "Porcelain tile", "Paint", "Tile", "Doors", "Glass"]
};
let _matPhIdx = 0;
let _matPhText = "";
let _matPhPhase = "typing"; // typing -> hold -> deleting
let _matPhTimer = null;

function ensureMaterialPlaceholderTicker() {
  if (_matPhTimer) return;
  const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const step = () => {
    const el = document.getElementById("mat-ph-word");
    const inp = document.getElementById("lib-materials-search-input");
    if (!el) { _matPhTimer = null; return; }
    if (document.hidden || (inp && inp.value)) { _matPhTimer = setTimeout(step, 1000); return; }
    const curMatLang = getMaterialsLang();
    const wordList = MAT_PH_WORDS_I18N[curMatLang] || MAT_PH_WORDS_I18N.ru;
    const word = wordList[_matPhIdx % wordList.length];
    let delay = 90;
    if (reduce) {
      _matPhText = word;
      el.textContent = word;
      _matPhIdx = (_matPhIdx + 1) % wordList.length;
      _matPhTimer = setTimeout(step, 2400);
      return;
    }
    if (_matPhPhase === "typing") {
      _matPhText = word.slice(0, _matPhText.length + 1);
      delay = 85 + Math.random() * 60;
      if (_matPhText.length >= word.length) { _matPhPhase = "hold"; delay = 1500; }
    } else if (_matPhPhase === "hold") {
      _matPhPhase = "deleting";
      delay = 60;
    } else {
      _matPhText = _matPhText.slice(0, -1);
      delay = 38;
      if (!_matPhText.length) {
        _matPhPhase = "typing";
        _matPhIdx = (_matPhIdx + 1) % wordList.length;
        delay = 320;
      }
    }
    el.textContent = _matPhText;
    _matPhTimer = setTimeout(step, delay);
  };
  _matPhTimer = setTimeout(step, 250);
}

// ---- Bo'lim UI ----
function getScopedMaterials() {
  const scope = materialsState.selectedScope || "all";
  let list = materialsState.allMaterials || [];
  if (scope === "architecture") list = list.filter(m => m.scope === "architecture" || m.scope === "both");
  else if (scope === "interior") list = list.filter(m => m.scope === "interior" || m.scope === "both");
  return list;
}

function getMaterialGroupsWithCounts() {
  const map = new Map();
  getScopedMaterials().forEach(m => {
    const g = getMaterialGroup(m);
    if (!map.has(g.id)) map.set(g.id, { ...g, count: 0 });
    map.get(g.id).count++;
  });
  const ordered = [];
  MATERIAL_GROUPS.forEach(g => { if (map.has(g.id)) ordered.push(map.get(g.id)); });
  map.forEach((g, id) => { if (!MATERIAL_GROUPS.some(x => x.id === id)) ordered.push(g); });
  return ordered;
}

function getGroupSubcategories(groupId) {
  const inGroup = getScopedMaterials().filter(m => getMaterialGroup(m).id === groupId);
  const counts = new Map();
  inGroup.forEach(m => { const s = (m.subcategory_name || "").trim(); if (s) counts.set(s, (counts.get(s) || 0) + 1); });
  if (counts.size < 2 || inGroup.length < 6) return [];
  return [...counts.entries()].sort((a, b) => b[1] - a[1]).map(([name, n]) => ({ name, n }));
}

function renderMaterialPanelInnerHtml() {
  const groups = getMaterialGroupsWithCounts();
  const active = materialsState.selectedGroup || "all";
  const scope = materialsState.selectedScope || "all";
  const total = getScopedMaterials().length;
  return `
    <div class="mcat-panel-title">${escapeHtml(matT('categories_title'))}</div>
    <div class="mcat-group-grid">
      <button type="button" class="mcat-group-tile ${active === "all" ? "active" : ""}" onclick="setMaterialGroup('all')">
        <span class="mcat-group-ico">🌐</span>
        <span class="mcat-group-name">${escapeHtml(matT('all_materials'))}</span>
        <span class="mcat-group-count">${total}</span>
      </button>
      ${groups.map(g => `
        <button type="button" class="mcat-group-tile ${active === g.id ? "active" : ""}" onclick="setMaterialGroup('${escapeJsString(g.id)}')">
          <span class="mcat-group-ico">${escapeHtml(g.icon || "🧱")}</span>
          <span class="mcat-group-name">${escapeHtml(getLocalizedGroupName(g))}</span>
          <span class="mcat-group-count">${g.count}</span>
        </button>
      `).join("")}
    </div>
    <div class="mcat-panel-title" style="margin-top:14px;">${escapeHtml(matT('extra_filters'))}</div>
    <div class="mcat-chip-row">
      <button type="button" class="mcat-chip ${scope === "all" ? "active" : ""}" onclick="setMaterialScope('all')">${escapeHtml(matT('all_chip'))}</button>
      <button type="button" class="mcat-chip ${scope === "architecture" ? "active" : ""}" onclick="setMaterialScope('architecture')">${escapeHtml(matT('filter_arch'))}</button>
      <button type="button" class="mcat-chip ${scope === "interior" ? "active" : ""}" onclick="setMaterialScope('interior')">${escapeHtml(matT('filter_interior'))}</button>
      <button type="button" class="mcat-chip ${materialsState.filterVerified ? "active" : ""}" onclick="toggleMaterialFilter('filterVerified')">${escapeHtml(matT('filter_verified'))}</button>
      <button type="button" class="mcat-chip ${materialsState.filterMoisture ? "active" : ""}" onclick="toggleMaterialFilter('filterMoisture')">${escapeHtml(matT('filter_moisture'))}</button>
      <button type="button" class="mcat-chip ${materialsState.filterFire ? "active" : ""}" onclick="toggleMaterialFilter('filterFire')">${escapeHtml(matT('filter_fire'))}</button>
    </div>
  `;
}

function renderMaterialActiveFilterHtml() {
  const grpId = materialsState.selectedGroup || "all";
  if (grpId === "all") return "";
  const g = getMaterialGroupsWithCounts().find(x => x.id === grpId) || MATERIAL_GROUPS.find(x => x.id === grpId);
  const subs = getGroupSubcategories(grpId);
  const activeSub = materialsState.selectedSubcategory || "all";
  const lang = getMaterialsLang();
  const getSubTitle = (name) => (SUBCAT_I18N[name] && SUBCAT_I18N[name][lang]) ? SUBCAT_I18N[name][lang] : name;
  return `
    <div class="mcat-active">
      <div class="mcat-active-chip">
        <span class="mcat-active-label">${escapeHtml(matT('category_label'))}:</span>
        <span class="mcat-active-name">${escapeHtml(g ? getLocalizedGroupName(g) : "")}</span>
        <button type="button" class="mcat-active-x" aria-label="Clear filter" onclick="clearMaterialCategoryFilter()">×</button>
      </div>
    </div>
    ${subs.length ? `
      <div class="mcat-sub-row">
        <button type="button" class="mcat-chip ${activeSub === "all" ? "active" : ""}" onclick="setMaterialSubcategory('all')">${escapeHtml(matT('all'))}</button>
        ${subs.map(s => `<button type="button" class="mcat-chip ${activeSub.toLowerCase() === s.name.toLowerCase() ? "active" : ""}" onclick="setMaterialSubcategory('${escapeJsString(s.name)}')">${escapeHtml(getSubTitle(s.name))} <span class="mcat-chip-n">${s.n}</span></button>`).join("")}
      </div>
    ` : ""}
  `;
}

function getPopularMaterials() {
  const base = getScopedMaterials();
  const scored = base.filter(m => getMaterialScore(m) > 0).sort((a, b) => getMaterialScore(b) - getMaterialScore(a) || b.id - a.id);
  let list = scored.slice(0, 10);
  if (list.length < 5) {
    // Faollik hali kam: admin "ko‘p ishlatiladigan" deb belgilaganlar bilan to‘ldiriladi
    const ids = new Set(list.map(m => m.id));
    base.filter(m => m.is_frequent && !ids.has(m.id)).forEach(m => { if (list.length < 8) list.push(m); });
  }
  return list;
}

function renderMaterialPopularHtml() {
  return "";
}

function renderMaterialCatalogHtml() {
  const mats = materialsState.materials || [];
  const grpId = materialsState.selectedGroup || "all";
  const search = (materialsState.searchQuery || "").trim();
  const sort = materialsState.sortBy || "popular";
  const flat = grpId !== "all" || !!search || materialsState.filterVerified || materialsState.filterMoisture || materialsState.filterFire || materialsState.filterInterior || (materialsState.selectedScope || "all") !== "all";

  const groupObj = grpId !== "all" ? (MATERIAL_GROUPS.find(x => x.id === grpId) || getMaterialGroupsWithCounts().find(x => x.id === grpId)) : null;
  const sectionTitle = groupObj ? getLocalizedGroupName(groupObj) : matT('all_materials');

  const head = `
    <div class="mcat-section-head">
      <h2 class="mcat-h2">${escapeHtml(sectionTitle)} <span class="mcat-h2-n">${mats.length}</span></h2>
      <label class="mcat-sort-wrap">
        <span class="mcat-sr">Sort</span>
        <select class="mcat-sort" onchange="setMaterialSort(this.value)" aria-label="Sort">
          <option value="popular" ${sort === "popular" ? "selected" : ""}>${escapeHtml(matT('popular_score'))}</option>
          <option value="views" ${sort === "views" ? "selected" : ""}>${escapeHtml(matT('views'))}</option>
          <option value="saves" ${sort === "saves" ? "selected" : ""}>${escapeHtml(matT('saves'))}</option>
          <option value="newest" ${sort === "newest" ? "selected" : ""}>${escapeHtml(matT('newest'))}</option>
          <option value="name" ${sort === "name" ? "selected" : ""}>${escapeHtml(matT('name_asc'))}</option>
        </select>
      </label>
    </div>`;

  if (!mats.length) {
    return head + `
      <div class="mcat-empty">
        <div class="mcat-empty-ico">🔍</div>
        <div class="mcat-empty-title">${escapeHtml(matT('not_found_title'))}</div>
        <div class="mcat-empty-sub">${escapeHtml(matT('not_found_sub'))}</div>
      </div>`;
  }

  if (flat) {
    const limit = materialsState.displayLimit || 36;
    const displayMats = mats.slice(0, limit);
    const hasMore = mats.length > displayMats.length;
    return head + `
      <div class="mcat-grid">${displayMats.map(renderMaterialCardHtml).join("")}</div>
      ${hasMore ? `
        <div style="text-align:center; padding:18px 0 10px;">
          <button type="button" class="mcat-chip" style="padding:10px 24px; font-weight:700; font-size:13px;" onclick="loadMoreMaterials()">
            Yana ko‘rsatish (${mats.length - displayMats.length} ta qoldi)
          </button>
        </div>
      ` : ''}
    `;
  }

  const byGroup = new Map();
  mats.forEach(m => {
    const g = getMaterialGroup(m);
    if (!byGroup.has(g.id)) byGroup.set(g.id, { g, items: [] });
    byGroup.get(g.id).items.push(m);
  });
  const ordered = [];
  MATERIAL_GROUPS.forEach(g => { if (byGroup.has(g.id)) ordered.push(byGroup.get(g.id)); });
  byGroup.forEach((v, id) => { if (!MATERIAL_GROUPS.some(x => x.id === id)) ordered.push(v); });

  return head + ordered.map(({ g, items }) => {
    const previewItems = items.slice(0, 6);
    const hasMoreInGroup = items.length > 6;
    return `
      <section class="mcat-group-section">
        <div class="mcat-group-head">
          <div class="mcat-group-title"><span>${escapeHtml(g.icon || "🧱")}</span> ${escapeHtml(getLocalizedGroupName(g))} <span class="mcat-h2-n">${items.length}</span></div>
          <button type="button" class="mcat-link" onclick="setMaterialGroup('${escapeJsString(g.id)}')">${escapeHtml(matT('all'))} (${items.length}) ›</button>
        </div>
        <div class="mcat-grid">${previewItems.map(renderMaterialCardHtml).join("")}</div>
        ${hasMoreInGroup ? `
          <div style="text-align:center; margin-top:8px;">
            <button type="button" class="mcat-chip" style="min-height:34px; font-size:12px; color:var(--text-secondary);" onclick="setMaterialGroup('${escapeJsString(g.id)}')">
              ${escapeHtml(getLocalizedGroupName(g))} — barcha ${items.length} ta materialni ko‘rish →
            </button>
          </div>
        ` : ''}
      </section>
    `;
  }).join("");
}

function loadMoreMaterials() {
  haptic("light");
  materialsState.displayLimit = (materialsState.displayLimit || 36) + 36;
  updateMaterialsUiInPlace();
}


function setMaterialsViewTab(tab) {
  haptic("light");
  if (tab !== "catalog" && tab !== "liked" && tab !== "saved") tab = "catalog";
  // If tapping already active tab (e.g. liked or saved), toggle back to catalog
  if (materialsState.currentViewTab === tab && tab !== "catalog") {
    materialsState.currentViewTab = "catalog";
  } else {
    materialsState.currentViewTab = tab;
  }
  materialsState.savedFilterModalOpen = false;
  render();
  window.scrollTo({ top: 0, left: 0, behavior: "smooth" });
}

function setSavedCategoryFilter(catId) {
  haptic("light");
  materialsState.savedFilterCategory = catId || "all";
  materialsState.savedFilterModalOpen = false;
  updateMaterialsUiInPlace();
}

function toggleSavedFilterModal(open) {
  haptic("light");
  if (typeof open === "boolean") {
    materialsState.savedFilterModalOpen = open;
  } else {
    materialsState.savedFilterModalOpen = !materialsState.savedFilterModalOpen;
  }
  const modal = document.getElementById("mcat-saved-filter-modal");
  if (modal) {
    modal.style.display = materialsState.savedFilterModalOpen ? "flex" : "none";
  }
}

function renderMaterialLikedViewHtml() {
  const lang = getMaterialsLang();
  const likedMaterials = (materialsState.allMaterials || []).filter(m => materialsState.likedIds && materialsState.likedIds.has(Number(m.id)));
  const count = likedMaterials.length;

  return `
    <div class="mcat-special-view">
      <div class="mcat-special-header" style="margin-bottom:14px;">
        <h2 class="mcat-h2" style="font-size:20px; font-weight:800; display:flex; align-items:center; gap:8px;">
          <span style="color:#ef4444;">♥</span> ${escapeHtml(matT('liked_title'))}
          <span class="mcat-h2-n" style="font-size:14px;">${count}</span>
        </h2>
        <p class="mcat-sub" style="margin:2px 0 0 0;">${count} ${escapeHtml(matT('items_count'))}</p>
      </div>

      ${count === 0 ? `
        <div class="mcat-empty" style="padding:60px 20px; text-align:center;">
          <div class="mcat-empty-ico" style="font-size:46px; color:#ef4444; margin-bottom:8px;">♡</div>
          <div class="mcat-empty-title" style="font-size:16px; font-weight:750; margin-bottom:4px;">${escapeHtml(matT('liked_empty_title'))}</div>
          <div class="mcat-empty-sub" style="font-size:13px; color:var(--text-muted); max-width:320px; margin:0 auto 16px auto;">${escapeHtml(matT('liked_empty_sub'))}</div>
          <button type="button" class="lib-page-btn" style="background:var(--accent, #007aff); color:#fff; border-radius:18px; padding:9px 22px; font-weight:700; border:none; cursor:pointer;" onclick="setMaterialsViewTab('catalog')">
            ${escapeHtml(matT('browse_catalog'))}
          </button>
        </div>
      ` : `
        <div class="mcat-grid">${likedMaterials.map(renderMaterialCardHtml).join("")}</div>
      `}
    </div>
  `;
}

function renderMaterialSavedViewHtml() {
  const lang = getMaterialsLang();
  const savedMaterials = (materialsState.allMaterials || []).filter(m => materialsState.savedIds && materialsState.savedIds.has(Number(m.id)));
  
  // Extract categories dynamically that strictly exist among saved materials
  const catMap = new Map();
  savedMaterials.forEach(m => {
    const g = getMaterialGroup(m);
    if (!catMap.has(g.id)) {
      catMap.set(g.id, { id: g.id, icon: g.icon || "🧱", name: getLocalizedGroupName(g, lang), count: 0 });
    }
    catMap.get(g.id).count++;
  });
  const dynamicCategories = Array.from(catMap.values()).sort((a, b) => b.count - a.count);

  const activeCatId = materialsState.savedFilterCategory || "all";
  let filteredSaved = savedMaterials;
  if (activeCatId !== "all") {
    filteredSaved = savedMaterials.filter(m => getMaterialGroup(m).id === activeCatId);
  }

  const activeCatObj = dynamicCategories.find(c => c.id === activeCatId);
  const activeCatName = activeCatObj ? activeCatObj.name : "";

  return `
    <div class="mcat-special-view">
      <div class="mcat-special-header" style="display:flex; align-items:flex-start; justify-content:space-between; gap:10px; margin-bottom:14px; flex-wrap:wrap;">
        <div>
          <h2 class="mcat-h2" style="font-size:20px; font-weight:800; display:flex; align-items:center; gap:8px;">
            <span>🔖</span> ${escapeHtml(matT('saved_title'))}
            <span class="mcat-h2-n" style="font-size:14px;">${filteredSaved.length}${activeCatId !== "all" ? ` / ${savedMaterials.length}` : ""}</span>
          </h2>
          <p class="mcat-sub" style="margin:2px 0 0 0;">${filteredSaved.length} ${escapeHtml(matT('items_count'))}</p>
        </div>

        ${savedMaterials.length > 0 ? `
          <div style="position:relative;">
            <button type="button" class="mcat-saved-filter-trigger" style="padding:6px 14px; font-size:13px; font-weight:700; border-radius:18px; border:1px solid var(--border, rgba(255,255,255,0.15)); background:var(--bg-surface-elevated, rgba(255,255,255,0.08)); color:var(--text-primary); cursor:pointer; display:inline-flex; align-items:center; gap:6px; user-select:none;" onclick="toggleSavedFilterModal()">
              <span>⚡ ${escapeHtml(matT('filter_btn'))}</span>
              <svg width="10" height="6" viewBox="0 0 10 6" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M1 1l4 4 4-4"/></svg>
            </button>
          </div>
        ` : ""}
      </div>

      <!-- Active category chip -->
      ${activeCatId !== "all" && activeCatObj ? `
        <div style="margin-bottom:14px; display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
          <div class="mcat-active-chip" style="display:inline-flex; align-items:center; gap:6px; background:rgba(0,122,255,0.12); color:#007aff; border:1px solid rgba(0,122,255,0.3); padding:5px 12px; border-radius:16px; font-size:12.5px; font-weight:700;">
            <span>${escapeHtml(activeCatObj.icon)} ${escapeHtml(activeCatName)}</span>
            <button type="button" class="mcat-active-x" style="background:none; border:none; color:#007aff; cursor:pointer; font-size:14px; font-weight:800; padding:0 2px;" onclick="setSavedCategoryFilter('all')">×</button>
          </div>
          <button type="button" style="background:none; border:none; color:var(--text-muted, #888); font-size:12px; cursor:pointer; text-decoration:underline;" onclick="setSavedCategoryFilter('all')">
            ${escapeHtml(matT('clear_filter'))}
          </button>
        </div>
      ` : ""}

      ${savedMaterials.length === 0 ? `
        <div class="mcat-empty" style="padding:60px 20px; text-align:center;">
          <div class="mcat-empty-ico" style="font-size:46px; margin-bottom:8px;">🔖</div>
          <div class="mcat-empty-title" style="font-size:16px; font-weight:750; margin-bottom:4px;">${escapeHtml(matT('saved_empty_title'))}</div>
          <div class="mcat-empty-sub" style="font-size:13px; color:var(--text-muted); max-width:320px; margin:0 auto 16px auto;">${escapeHtml(matT('saved_empty_sub'))}</div>
          <button type="button" class="lib-page-btn" style="background:var(--accent, #007aff); color:#fff; border-radius:18px; padding:9px 22px; font-weight:700; border:none; cursor:pointer;" onclick="setMaterialsViewTab('catalog')">
            ${escapeHtml(matT('browse_catalog'))}
          </button>
        </div>
      ` : (filteredSaved.length === 0 ? `
        <div class="mcat-empty" style="padding:50px 20px; text-align:center;">
          <div class="mcat-empty-ico" style="font-size:40px; margin-bottom:8px;">🔍</div>
          <div class="mcat-empty-title" style="font-size:15.5px; font-weight:750; margin-bottom:4px;">${escapeHtml(matT('filter_empty_title'))}</div>
          <div class="mcat-empty-sub" style="font-size:13px; color:var(--text-muted); margin-bottom:14px;">${escapeHtml(matT('filter_empty_sub'))}</div>
          <button type="button" class="lib-page-btn" style="background:rgba(255,255,255,0.08); color:var(--text-primary); border-radius:18px; padding:8px 18px; font-weight:700; border:1px solid var(--border); cursor:pointer;" onclick="setSavedCategoryFilter('all')">
            ${escapeHtml(matT('all_chip'))} (${savedMaterials.length})
          </button>
        </div>
      ` : `
        <div class="mcat-grid">${filteredSaved.map(renderMaterialCardHtml).join("")}</div>
      `)}

      <!-- Saved Categories Filter Modal / Bottom Sheet -->
      <div id="mcat-saved-filter-modal" class="mcat-modal-backdrop" style="display:${materialsState.savedFilterModalOpen ? 'flex' : 'none'}; position:fixed; inset:0; z-index:9999; background:rgba(0,0,0,0.65); backdrop-filter:blur(6px); -webkit-backdrop-filter:blur(6px); align-items:flex-end; justify-content:center;" onclick="if(event.target===this) toggleSavedFilterModal(false)">
        <div class="mcat-filter-sheet" style="width:100%; max-width:480px; max-height:85vh; background:var(--bg-surface-elevated, #1c1c1e); border-top-left-radius:24px; border-top-right-radius:24px; padding:20px; box-shadow:0 -10px 40px rgba(0,0,0,0.5); overflow-y:auto; border-top:1px solid var(--border, rgba(255,255,255,0.1));" onclick="event.stopPropagation()">
          <div style="width:36px; height:4px; border-radius:2px; background:rgba(255,255,255,0.25); margin:0 auto 16px auto;"></div>
          <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:14px;">
            <h3 style="margin:0; font-size:17px; font-weight:800; color:var(--text-primary);">${escapeHtml(matT('filter_btn'))}</h3>
            <button type="button" style="background:none; border:none; font-size:18px; color:var(--text-muted); cursor:pointer; padding:4px 8px;" onclick="toggleSavedFilterModal(false)">✕</button>
          </div>
          <div style="display:flex; flex-direction:column; gap:6px;">
            <button type="button" class="mcat-filter-sheet-opt ${activeCatId === 'all' ? 'active' : ''}" style="display:flex; align-items:center; justify-content:space-between; padding:11px 14px; border-radius:12px; border:none; background:${activeCatId === 'all' ? 'rgba(0,122,255,0.14)' : 'rgba(255,255,255,0.04)'}; color:${activeCatId === 'all' ? '#007aff' : 'var(--text-primary)'}; font-size:14px; font-weight:700; cursor:pointer; text-align:left;" onclick="setSavedCategoryFilter('all')">
              <span style="display:inline-flex; align-items:center; gap:8px;">
                <span>🌐</span> ${escapeHtml(matT('all_chip'))}
              </span>
              <span style="font-size:12px; opacity:0.75;">${savedMaterials.length} ${activeCatId === 'all' ? '✓' : ''}</span>
            </button>
            ${dynamicCategories.map(c => `
              <button type="button" class="mcat-filter-sheet-opt ${activeCatId === c.id ? 'active' : ''}" style="display:flex; align-items:center; justify-content:space-between; padding:11px 14px; border-radius:12px; border:none; background:${activeCatId === c.id ? 'rgba(0,122,255,0.14)' : 'rgba(255,255,255,0.04)'}; color:${activeCatId === c.id ? '#007aff' : 'var(--text-primary)'}; font-size:14px; font-weight:700; cursor:pointer; text-align:left;" onclick="setSavedCategoryFilter('${escapeJsString(c.id)}')">
                <span style="display:inline-flex; align-items:center; gap:8px;">
                  <span>${escapeHtml(c.icon)}</span> ${escapeHtml(c.name)}
                </span>
                <span style="font-size:12px; opacity:0.75;">${c.count} ${activeCatId === c.id ? '✓' : ''}</span>
              </button>
            `).join("")}
          </div>
        </div>
      </div>
    </div>
  `;
}

// ======================================================
// MATERIALLAR + JIHOZLAR — bitta bo'lim, ikki tab
// Jihozlar endi Kutubxonada alohida karta emas: Materiallar ichidan ochiladi.
// ======================================================
function renderMaterialsKindSwitchHtml(active) {
  return `
    <div class="kind-switch" role="tablist" aria-label="Materiallar va jihozlar">
      <button type="button" role="tab" aria-selected="${active === 'materials'}" class="kind-switch-btn ${active === 'materials' ? 'active' : ''}" onclick="switchMaterialsKind('materials')">Materiallar</button>
      <button type="button" role="tab" aria-selected="${active === 'equipment'}" class="kind-switch-btn ${active === 'equipment' ? 'active' : ''}" onclick="switchMaterialsKind('equipment')">Jihozlar</button>
    </div>`;
}

function switchMaterialsKind(kind) {
  if (kind !== 'materials' && kind !== 'equipment') return;
  if (libraryActiveSection === kind) return;
  if (kind === 'materials' && typeof equipmentUi !== "undefined") {
    window.dispatchEvent(new Event("equipmentUi:reset"));
  }
  openLibrarySection(kind);
}

function renderMaterialsSectionHtml() {
  if (!materialsState.loaded && !materialsState.loading) {
    loadMaterialsData().then(() => {
      if (libraryActiveSection === "materials") render();
    });
  }

  if (materialsState.loading && !materialsState.loaded) {
    return `
      <div class="page lib-container lib-page-enter lib-materials-v2-container">
        <div class="lib-back-nav" onclick="closeLibrarySection()">
          ${libIcons.back('lib-back-svg', 16)} Kutubxona
        </div>
        <div style="padding: 80px 20px; text-align: center;">
          <div class="spinner" style="margin: 0 auto 16px;"></div>
          <div style="font-weight: 700; font-size: 15px; color: var(--text-primary); margin-bottom: 6px;">Materiallar katalogi yuklanmoqda...</div>
        </div>
      </div>
    `;
  }

  ensureMaterialPlaceholderTicker();
  ensureMaterialCardRotationTicker();
  const search = materialsState.searchQuery || "";
  const open = !!materialsState.panelOpen;

  const isSpecialTab = materialsState.currentViewTab === 'liked' || materialsState.currentViewTab === 'saved';
  const lCount = materialsState.likedIds ? materialsState.likedIds.size : 0;
  const sCount = materialsState.savedIds ? materialsState.savedIds.size : 0;

  return `
    <div class="page lib-container lib-page-enter lib-materials-v2-container mcat">
      <div class="lib-materials-header-nav" style="display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:12px; flex-wrap:wrap;">
        <div class="lib-back-nav" style="margin-bottom:0;" onclick="${isSpecialTab ? 'setMaterialsViewTab(\'catalog\')' : 'closeLibrarySection()'}">
          ${libIcons.back('lib-back-svg', 16)} ${escapeHtml(isSpecialTab ? matT('back_catalog') : (matT('back_lib_text') || 'Библиотека'))}
        </div>
        <div class="mcat-top-nav-row" style="display:flex; align-items:center; gap:6px; flex-wrap:nowrap;">
          ${renderMaterialsLangSelectorHtml()}
          <button type="button" class="mcat-nav-tab-btn ${materialsState.currentViewTab === 'liked' ? 'active' : ''}" onclick="setMaterialsViewTab('liked')">
            <span class="mcat-nav-tab-ico" style="color:${materialsState.currentViewTab === 'liked' ? '#fff' : (lCount > 0 ? '#ef4444' : 'inherit')}">${lCount > 0 ? '♥' : '♡'}</span>
            <span class="mcat-nav-tab-text">${escapeHtml(matT('liked_tab_title'))}</span>
            <span id="mcat-like-badge" class="mcat-nav-tab-badge" style="display:${lCount > 0 ? 'inline-flex' : 'none'};">${lCount}</span>
          </button>
          <button type="button" class="mcat-nav-tab-btn ${materialsState.currentViewTab === 'saved' ? 'active' : ''}" onclick="setMaterialsViewTab('saved')">
            <span class="mcat-nav-tab-ico">🔖</span>
            <span class="mcat-nav-tab-text">${escapeHtml(matT('saved_tab_title'))}</span>
            <span id="mcat-save-badge" class="mcat-nav-tab-badge" style="display:${sCount > 0 ? 'inline-flex' : 'none'};">${sCount}</span>
          </button>
        </div>
      </div>

      ${isSpecialTab ? '' : renderMaterialsKindSwitchHtml('materials')}

      ${materialsState.currentViewTab === 'liked' ? renderMaterialLikedViewHtml() : (
        materialsState.currentViewTab === 'saved' ? renderMaterialSavedViewHtml() : `
          <div class="mcat-head">
            <h1 class="mcat-title">${escapeHtml(matT('materials_catalog_title'))}</h1>
            <p class="mcat-sub">${escapeHtml(matT('materials_catalog_sub'))}</p>
          </div>

          <div class="mcat-search">
            <span class="mcat-search-icon">${libIcons.search('lib-search-svg', 18)}</span>
            <input id="lib-materials-search-input" type="text" class="mcat-search-input" placeholder=" " autocomplete="off" autocapitalize="off" enterkeyhint="search"
                   value="${escapeHtml(search)}" oninput="setMaterialSearch(this.value)" />
            <div class="mcat-ph" aria-hidden="true"><span>${escapeHtml(matT('search_short'))}</span> <span class="mcat-ph-word" id="mat-ph-word">${escapeHtml(_matPhText)}</span></div>
            <span id="lib-search-clear-wrap">${search ? `<button class="lib-search-clear-btn" onclick="clearMaterialSearch()">✕</button>` : ""}</span>
          </div>

          <button type="button" id="mat-panel-btn" class="mcat-filter-btn ${open ? "open" : ""} ${(materialsState.selectedGroup || "all") !== "all" ? "has-filter" : ""}" onclick="toggleMaterialPanel()">
            <span class="mcat-filter-left">
              <svg viewBox="0 0 24 24" width="18" height="18" class="mcat-ico-stroke"><path d="M4 6h16M7 12h10M10 18h4"/></svg>
              ${escapeHtml(matT('filter_by_cats') || matT('categories_title'))}
            </span>
            <svg viewBox="0 0 24 24" width="18" height="18" class="mcat-chevron mcat-ico-stroke"><path d="M6 9l6 6 6-6"/></svg>
          </button>

          <div id="mat-panel" class="mcat-panel ${open ? "open" : ""}">
            <div class="mcat-panel-clip"><div class="mcat-panel-inner" id="mat-panel-inner">${renderMaterialPanelInnerHtml()}</div></div>
          </div>

          <div id="mat-active-filter">${renderMaterialActiveFilterHtml()}</div>
          <div id="mat-popular-wrap">${renderMaterialPopularHtml()}</div>
          <div id="mat-catalog-wrap">${renderMaterialCatalogHtml()}</div>
        `
      )}
    </div>
  `;
}


// ------------------------------------------------------
// MATERIALS MULTI-IMAGE ROTATION & INTERACTIVE GALLERY
// ------------------------------------------------------

let materialCardRotationInterval = null;
let activeMaterialGalleryIndex = 0;
let matGalleryTouchStartX = 0;
let matGalleryTouchEndX = 0;

function ensureMaterialCardRotationTicker() {
  if (materialCardRotationInterval) return;
  startMaterialCardRotationTicker();
}

function startMaterialCardRotationTicker() {
  if (materialCardRotationInterval) clearInterval(materialCardRotationInterval);

  // Initialize per-card staggered timing on first run
  _initCardStaggerTimings();

  // One master ticker at 1000ms — checks each card's individual schedule
  materialCardRotationInterval = setInterval(() => {
    // Only rotate if currently viewing materials catalog (not detail and not other section)
    if (libraryActiveSection !== "materials" || (currentView && currentView.type === "material_detail")) {
      return;
    }
    const cards = document.querySelectorAll('.mcat-card[data-images]');
    if (!cards || !cards.length) return;

    const now = Date.now();
    cards.forEach((card, i) => {
      // Pause rotation if hovered on desktop
      if (card.matches && card.matches(':hover')) return;

      try {
        // If not initialized yet (e.g. after re-render/filter), assign unique staggered schedule
        if (!card.hasAttribute('data-rotate-interval')) {
          const interval = 5000 + ((i * 2749 + 1301) % 7001);
          const delay = 1000 + ((i * 3571 + 2137) % 5001);
          card.setAttribute('data-rotate-interval', String(interval));
          card.setAttribute('data-next-rotate', String(now + delay));
          return;
        }

        // Check if this card's next rotation time has arrived
        const nextRotate = parseInt(card.getAttribute('data-next-rotate') || '0', 10);
        if (!nextRotate || now < nextRotate) return;

        const raw = card.getAttribute('data-images');
        if (!raw) return;
        const images = JSON.parse(raw);
        if (!Array.isArray(images) || images.length <= 1) return;

        let curIdx = parseInt(card.getAttribute('data-img-idx') || '0', 10);
        let nextIdx = (curIdx + 1) % images.length;
        card.setAttribute('data-img-idx', String(nextIdx));

        // Schedule next rotation for THIS card with its own interval
        const interval = parseInt(card.getAttribute('data-rotate-interval') || '7000', 10);
        card.setAttribute('data-next-rotate', String(now + interval));

        const imgEl = card.querySelector('.mcat-card-img img');
        if (imgEl && images[nextIdx]) {
          imgEl.classList.add('mcat-fade-out');
          setTimeout(() => {
            imgEl.src = formatImageUrl(images[nextIdx]);
            imgEl.classList.remove('mcat-fade-out');
          }, 200);
        }

        const dots = card.querySelectorAll('.mcat-card-dot');
        dots.forEach((dot, dIdx) => {
          dot.classList.toggle('active', dIdx === nextIdx);
        });
      } catch (e) {}
    });
  }, 1000);
}

/** Assign each card a unique rotation interval and staggered initial delay */
function _initCardStaggerTimings() {
  const cards = document.querySelectorAll('.mcat-card[data-images]');
  if (!cards || !cards.length) return;
  const now = Date.now();
  cards.forEach((card, i) => {
    if (card.getAttribute('data-rotate-interval')) return; // already initialized
    // Deterministic pseudo-random interval between 5000-12000ms
    const interval = 5000 + ((i * 2749 + 1301) % 7001);
    // Deterministic pseudo-random initial delay between 1000-6000ms
    const delay = 1000 + ((i * 3571 + 2137) % 5001);
    card.setAttribute('data-rotate-interval', String(interval));
    card.setAttribute('data-next-rotate', String(now + delay));
  });
}

function stopMaterialCardRotationTicker() {
  if (materialCardRotationInterval) {
    clearInterval(materialCardRotationInterval);
    materialCardRotationInterval = null;
  }
}

function selectMaterialGalleryImage(idx) {
  haptic("light");
  const m = activeMaterialDetail ? (activeMaterialDetail.material || activeMaterialDetail) : null;
  if (!m) return;
  const images = (Array.isArray(m.images) && m.images.length ? m.images : [m.image_url || m.cover_image]).filter(Boolean);
  if (!images.length) return;
  activeMaterialGalleryIndex = Math.max(0, Math.min(idx, images.length - 1));
  updateMaterialGalleryUi(images);
}

function navigateMaterialGallery(delta) {
  haptic("light");
  const m = activeMaterialDetail ? (activeMaterialDetail.material || activeMaterialDetail) : null;
  if (!m) return;
  const images = (Array.isArray(m.images) && m.images.length ? m.images : [m.image_url || m.cover_image]).filter(Boolean);
  if (images.length <= 1) return;
  activeMaterialGalleryIndex = (activeMaterialGalleryIndex + delta + images.length) % images.length;
  updateMaterialGalleryUi(images);
}

function updateMaterialGalleryUi(images) {
  const imgEl = document.getElementById("lib-mat-gallery-img");
  const counterEl = document.getElementById("lib-mat-gallery-counter");
  if (imgEl && images[activeMaterialGalleryIndex]) {
    imgEl.classList.add("fade-out");
    setTimeout(() => {
      imgEl.src = formatImageUrl(images[activeMaterialGalleryIndex]);
      imgEl.classList.remove("fade-out");
    }, 150);
  }
  if (counterEl) {
    counterEl.textContent = (activeMaterialGalleryIndex + 1) + " / " + images.length;
  }
  const thumbs = document.querySelectorAll(".lib-mat-thumb-btn");
  thumbs.forEach((th, i) => {
    th.classList.toggle("active", i === activeMaterialGalleryIndex);
  });
}

function handleGalleryTouchStart(e) {
  if (e.changedTouches && e.changedTouches[0]) {
    matGalleryTouchStartX = e.changedTouches[0].clientX;
  }
}

function handleGalleryTouchEnd(e) {
  if (e.changedTouches && e.changedTouches[0]) {
    matGalleryTouchEndX = e.changedTouches[0].clientX;
    const diff = matGalleryTouchEndX - matGalleryTouchStartX;
    if (Math.abs(diff) > 40) {
      if (diff > 0) {
        navigateMaterialGallery(-1);
      } else {
        navigateMaterialGallery(1);
      }
    }
  }
}

// Global desktop keyboard arrow navigation for gallery
window.addEventListener("keydown", (e) => {
  if (currentView && currentView.type === "material_detail") {
    if (e.key === "ArrowLeft") navigateMaterialGallery(-1);
    if (e.key === "ArrowRight") navigateMaterialGallery(1);
  }
});

function renderMaterialCardHtml(mat) {
  const title = getMaterialTitle(mat);
  const images = (Array.isArray(mat.images) && mat.images.length ? mat.images : [mat.image_url || mat.cover_image || mat.featured_image]).filter(Boolean);
  const initIdx = images.length > 1 ? Math.floor(Math.random() * images.length) : 0;
  const activeImg = formatImageUrl(images[initIdx] || mat.image_url || mat.cover_image || "");
  const g = getMaterialGroup(mat);
  const tag = getMaterialSubcategory(mat);
  const desc = getMaterialDesc(mat);
  const dim = getMaterialDimensions(mat);
  return `
    <div class="mcat-card" onclick="openMaterialKnowledgeDetail(${Number(mat.id)})"
         ${images.length > 1 ? `data-images="${escapeHtml(JSON.stringify(images))}" data-img-idx="${initIdx}"` : ""}>
      <div class="mcat-card-img">
        <span class="mcat-ph-emoji">${escapeHtml(g.icon || mat.category_icon || "🧱")}</span>
        ${activeImg ? `<img src="${escapeHtml(activeImg)}" loading="lazy" decoding="async" alt="${escapeHtml(title)}" onerror="this.style.display='none';" />` : ""}
        ${images.length > 1 ? `
          <div class="mcat-card-dots" aria-hidden="true">
            ${images.map((_, dIdx) => `<span class="mcat-card-dot ${dIdx === initIdx ? 'active' : ''}"></span>`).join('')}
          </div>
        ` : ""}
        <div class="mcat-card-actions">
          ${matReactionButtonHtml(mat.id, "like", true)}
          ${matReactionButtonHtml(mat.id, "save", true)}
        </div>
      </div>
      <div class="mcat-card-body">
        <div class="mcat-card-cat">${escapeHtml(tag)}</div>
        <h3 class="mcat-card-title">${escapeHtml(title)}</h3>
        ${desc ? `<p class="mcat-card-desc">${escapeHtml(desc)}</p>` : ""}
        ${dim ? `<div class="mcat-card-meta">📏 ${escapeHtml(String(dim).slice(0, 40))}</div>` : ""}
      </div>
    </div>
  `;
}

