function formatFileSizeUz(raw) {
  if (raw === null || raw === undefined) return "";
  const s = String(raw).trim();
  if (!s) return "";
  const m = s.replace(",", ".").match(/^([\d.]+)\s*(kb|mb|gb|tb)?/i);
  if (!m) return s;
  const n = parseFloat(m[1]);
  if (!isFinite(n) || n <= 0) return "";
  const u = (m[2] || "mb").toLowerCase();
  const mb = u === "kb" ? n / 1024 : u === "gb" ? n * 1024 : u === "tb" ? n * 1024 * 1024 : n;
  if (mb >= 1000) return (Math.round(mb / 1024 * 10) / 10) + " GB";
  if (mb < 1) return Math.max(1, Math.round(mb * 1024)) + " KB";
  return (Math.round(mb * 10) / 10) + " MB";
}

let _driveSizeTimer = null;
function autoResolveDriveSize(prefix, now) {
  clearTimeout(_driveSizeTimer);
  _driveSizeTimer = setTimeout(async () => {
    const urlEl = document.getElementById(prefix + "-url");
    const sizeEl = document.getElementById(prefix + "-filesize");
    if (!urlEl || !sizeEl) return;
    const url = urlEl.value.trim();
    if (!/drive\.google\.com|docs\.google\.com|t\.me\/|telegram\.me\//i.test(url)) return;
    sizeEl.value = "Aniqlanmoqda...";
    try {
      const r = await adminApi("/api/admin/library-v2/resolve-size", { url });
      sizeEl.value = r && r.ok ? r.file_size : "";
      if (!(r && r.ok)) showAlert((r && r.error) || "Hajm aniqlanmadi: havolani tekshiring");
    } catch (e) {
      sizeEl.value = "";
    }
  }, now ? 0 : 600);
}

async function submitCreateLibraryV2Resource() {
  const sectionSlug = document.getElementById("v2-sec")?.value || "books";
  const type = document.getElementById("v2-type")?.value || "book";
  const title = document.getElementById("v2-title")?.value.trim();
  const subtitle = document.getElementById("v2-sub")?.value.trim();
  const category = document.getElementById("v2-cat")?.value;
  const author = document.getElementById("v2-author")?.value.trim();
  const version = document.getElementById("v2-version")?.value.trim();
  const softwareVal = document.getElementById("v2-software")?.value || "";
  const formatVal = document.getElementById("v2-format")?.value || "";
  const fileSize = document.getElementById("v2-filesize")?.value.trim();
  const courseId = document.getElementById("v2-course-id")?.value ? Number(document.getElementById("v2-course-id").value) : null;
  const contentUrl = document.getElementById("v2-url")?.value.trim();
  const previewImageUrl = document.getElementById("v2-cover")?.value.trim();
  const description = document.getElementById("v2-desc")?.value.trim();
  const isFeatured = Boolean(document.getElementById("v2-featured")?.checked);
  const status = document.getElementById("v2-status")?.value || "published";

  if (!title) return showAlert("Resurs nomi majburiy!");

  let contentType = "link";
  if (contentUrl) {
    if (contentUrl.includes("drive.google.com") || contentUrl.endsWith(".pdf")) contentType = "pdf";
    else if (contentUrl.includes("youtube.com") || contentUrl.includes("youtu.be")) contentType = "video";
  }

  try {
    haptic("medium");
    const addRes = await adminApi("/api/admin/library-v2/resource/add", {
      section_slug: sectionSlug,
      type: type,
      title: title,
      subtitle: subtitle,
      category: category,
      author: author,
      version: version,
      software: softwareVal || null,
      file_format: formatVal || null,
      file_size: fileSize,
      course_id: courseId,
      is_featured: isFeatured,
      content_url: contentUrl,
      content_type: contentType,
      preview_image_url: previewImageUrl,
      description: description,
      status: status
    });

    if (addRes && addRes.size_warning) showAlert("Resurs saqlandi, lekin hajmi aniqlanmadi: " + addRes.size_warning);
    else showToast("Resurs muvaffaqiyatli qo'shildi!");
    await loadLibraryV2Data(true);
    adminSetTab("library");
  } catch (err) {
    showAlert(err.message || "Resurs qo'shishda xato yuz berdi.");
  }
}

