let lastNavTapTime = 0;
let lastNavTapId = null;

function renderNav() {
  const tabs = [
    { id: "home", label: "Bosh sahifa" },
    { id: "lessons", label: "Darslar" },
    { id: "tasks", label: "Kutubxona" },
    { id: "chat", label: "Chat" },
    { id: "profile", label: "Profil" }
  ];

  return `
    <div class="nav">
      ${tabs.map(t => {
        const isActive = activeTab === t.id;
        const icon = NAV_ICONS[t.id];
        const svgInner = icon.outline;
        const strokeProps = `fill="none" stroke="currentColor" stroke-width="1.4"`;
        return `
        <div class="nav-item ${isActive ? "active" : ""}" data-tab="${t.id}" role="button" tabindex="0" aria-label="${t.label}" ${isActive ? 'aria-current="page"' : ''} onclick="setTab('${t.id}', event)" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();setTab('${t.id}', event);}">
          <div class="nav-icon">
            <svg class="nav-svg" viewBox="0 0 24 24" aria-hidden="true" ${strokeProps}>${svgInner}</svg>
          </div>
          <div class="nav-label">${t.label}</div>
        </div>
      `;
      }).join("")}
    </div>
  `;
}

function setTab(id, event) {
  touchActivity();
  if (!state.terms_accepted && !state.is_admin) {
    render();
    return;
  }

  const now = Date.now();
  const isDoubleTap = (lastNavTapId === id && (now - lastNavTapTime) < 450);
  const isAlreadyActive = (activeTab === id && !currentView);
  lastNavTapTime = now;
  lastNavTapId = id;

  haptic("light");

  // Ikonka animatsiyasini ishga tushirish (bounce / spring effekti)
  const clickedTarget = event ? event.currentTarget : document.querySelector(`.nav-item[data-tab="${id}"]`);
  if (clickedTarget) {
    clickedTarget.classList.remove("nav-item-bounce");
    void clickedTarget.offsetWidth; // reflow
    clickedTarget.classList.add("nav-item-bounce");
    setTimeout(() => {
      if (clickedTarget) clickedTarget.classList.remove("nav-item-bounce");
    }, 450);
  }

  // Double tap yoki ayni shu tab turgan paytda yana bosilsa -> Sahifani eng tepasiga ravon (smooth) chiqarib yuborish
  if (isDoubleTap || isAlreadyActive) {
    savedTabScrolls[id] = 0;
    // Agar Kutubxona ichidagi biror bo'limda (masalan, materiallar yoki kitoblar) bo'lsa
    if (id === "tasks" && libraryActiveSection) {
      const currentY = window.scrollY || window.pageYOffset || document.documentElement.scrollTop || 0;
      if (currentY > 40) {
        // Agar pastga tushilgan bo'lsa, eng tepasiga ko'taradi
        window.scrollTo({ top: 0, left: 0, behavior: "smooth" });
      } else {
        // Agar allaqachon tepasida bo'lsa, asosiy Kutubxona bosh sahifasiga qaytaradi
        closeLibrarySection();
      }
      return;
    }
    // Boshqa barcha bo'limlarda eng tepasiga chiqaradi
    window.scrollTo({ top: 0, left: 0, behavior: "smooth" });
    const sc = document.getElementById("app");
    if (sc && sc.scrollTop > 0) {
      sc.scrollTo({ top: 0, left: 0, behavior: "smooth" });
    }
    return;
  }

  if (!currentView) {
    savedTabScrolls[activeTab] = window.scrollY || window.pageYOffset || document.documentElement.scrollTop || 0;
  }
  activeTab = id;
  currentView = null;
  render();

  // Yangi aktiv bo'lgan ikonka animatsiyasi
  requestAnimationFrame(() => {
    const newActiveEl = document.querySelector(`.nav-item.active`);
    if (newActiveEl) {
      newActiveEl.classList.remove("nav-item-bounce");
      void newActiveEl.offsetWidth;
      newActiveEl.classList.add("nav-item-bounce");
      setTimeout(() => {
        if (newActiveEl) newActiveEl.classList.remove("nav-item-bounce");
      }, 450);
    }
  });

  const targetY = savedTabScrolls[id] || 0;
  requestAnimationFrame(() => {
    window.scrollTo({ top: targetY, left: 0, behavior: "instant" });
    setTimeout(() => {
      window.scrollTo({ top: targetY, left: 0, behavior: "instant" });
    }, 30);
  });
  if (id === "chat") {
    loadChatQuestions();
  }
  if (id === "tasks") {
    loadLibraryV2Data();
    preloadLibrarySubsections();
  }
  sendHeartbeat({ current_tab: id });
}

// Chegirma muddati uchun jonli sanoq (har soniyada barcha .discount-countdown elementlarini yangilaydi)
setInterval(() => {
  const countEls = document.querySelectorAll(".discount-countdown");
  if (!countEls.length) return;
  countEls.forEach(el => {
    const until = el.dataset.until ? new Date(el.dataset.until) : null;
    if (!until || isNaN(until.getTime())) return;
    const diff = until.getTime() - Date.now();
    if (diff <= 0) {
      el.textContent = "⏰ Chegirma muddati tugadi";
      return;
    }
    const days = Math.floor(diff / 86400000);
    const hours = Math.floor((diff % 86400000) / 3600000);
    const mins = Math.floor((diff % 3600000) / 60000);
    const secs = Math.floor((diff % 60000) / 1000);
    const pad = n => String(n).padStart(2, "0");
    el.textContent = days > 0
      ? `🔥 Chegirma tugashiga: ${days} kun ${pad(hours)}:${pad(mins)}:${pad(secs)}`
      : `🔥 Chegirma tugashiga: ${pad(hours)}:${pad(mins)}:${pad(secs)}`;
  });

  document.querySelectorAll(".retake-countdown").forEach(el => {
    const until = el.dataset.until ? new Date(el.dataset.until) : null;
    if (!until || isNaN(until.getTime())) return;
    const diff = until.getTime() - Date.now();
    if (diff <= 0) {
      el.textContent = "🔓 Testni qayta topshirish mumkin";
      return;
    }
    const days = Math.floor(diff / 86400000);
    const hours = Math.floor((diff % 86400000) / 3600000);
    const mins = Math.floor((diff % 3600000) / 60000);
    const secs = Math.floor((diff % 60000) / 1000);
    const pad = n => String(n).padStart(2, "0");
    el.textContent = days > 0
      ? `⏳ Qayta topshirish uchun: ${days} kun ${pad(hours)}:${pad(mins)}:${pad(secs)}`
      : `⏳ Qayta topshirish uchun: ${pad(hours)}:${pad(mins)}:${pad(secs)}`;
  });
}, 1000);

function closeDetail() {
  haptic("light");
  stopAdminLivePolling();
  clearActivitySpecialState();
  if (window._readerLoadTimeout) {
    clearTimeout(window._readerLoadTimeout);
    window._readerLoadTimeout = null;
  }
  clearTimeout(readingProgressSaveTimeout);
  if (window._quizState) {
    if (window._quizState.lockTimer) clearTimeout(window._quizState.lockTimer);
    window._quizState = null;
  }
  lastPdfReturnView = null;
  currentBookReaderId = null;
  currentView = null;
  activeMaterialDetail = null;
  const targetY = lastDetailReturnScroll || savedTabScrolls[activeTab] || 0;
  render();
  requestAnimationFrame(() => {
    window.scrollTo({ top: targetY, left: 0, behavior: "instant" });
    setTimeout(() => {
      window.scrollTo({ top: targetY, left: 0, behavior: "instant" });
    }, 40);
  });
}

function renderTab() {
  switch (activeTab) {
    case "home": return renderHome();
    case "lessons": return renderLessons();
    case "tasks": return renderTasks();
    case "chat": return renderChat();
    case "profile": return renderProfile();
    default: return renderHome();
  }
}

function updateTelegramBackButton() {
  try {
    if (!tg || !tg.BackButton) return;
    tg.BackButton.offClick(handleTelegramBackClick);
    if (currentView) {
      tg.BackButton.show();
      tg.BackButton.onClick(handleTelegramBackClick);
    } else if (activeTab === "tasks" && typeof libraryActiveSection !== "undefined" && libraryActiveSection) {
      tg.BackButton.show();
      tg.BackButton.onClick(handleTelegramBackClick);
    } else {
      tg.BackButton.hide();
    }
  } catch (e) {}
}

function handleTelegramBackClick() {
  if (document.getElementById("book-reader-view") || (currentView && (currentView.isReader || currentView.type === "book_reader"))) {
    closeBookReader();
    return;
  }
  if (currentView && currentView.isAdminPanel) {
    if (typeof adminNavPath !== "undefined" && Array.isArray(adminNavPath) && adminNavPath.length > 1) {
      adminGoBack();
      return;
    }
  }
  if (currentView) {
    if (currentView.type === "material_detail") {
      closeMaterialDetail();
    } else {
      closeDetail();
    }
  } else if (activeTab === "tasks" && typeof libraryActiveSection !== "undefined" && libraryActiveSection) {
    if (libraryActiveSection === "equipment" && typeof equipmentUi !== "undefined" && (equipmentUi.isDetailOpen() || equipmentUi.isListOpen())) {
      equipmentUi.back();
      return;
    }
    closeLibrarySection();
  }
}

// ======================================================
// LEARNING CENTER (ARXITEKTURA VA ISHCHI HUJJATLAR BAZASI)
// ======================================================

let learningState = {
  stages: [],
  resources: [],
  tables: [],
  completed_stages: [],
  has_access: false,
  loaded: false,
  loading: false
};
let learningFilter = "all";
let learningSearchQuery = "";
let learningExpandedStages = { 1: true };

async function loadLearningContent() {
  if (learningState.loading) return;
  learningState.loading = true;
  try {
    const data = await api("/api/learning/content");
    learningState = {
      ...learningState,
      stages: Array.isArray(data.stages) ? data.stages : [],
      resources: Array.isArray(data.resources) ? data.resources : [],
      tables: Array.isArray(data.tables) ? data.tables : [],
      completed_stages: Array.isArray(data.completed_stages) ? data.completed_stages : [],
      has_access: Boolean(data.has_access),
      loaded: true,
      loading: false
    };
  } catch (err) {
    console.error("LOAD LEARNING ERROR:", err);
    learningState.loading = false;
  }
}

async function openLearningCenter() {
  haptic("light");
  if (!learningState.loaded) {
    showToast("📚 O‘rganish markazi yuklanmoqda...");
    await loadLearningContent();
  }
  currentView = {
    type: "learning",
    html: renderLearningCenter()
  };
  render();
  window.scrollTo({ top: 0, left: 0, behavior: "auto" });
}

function setLearningFilter(filter) {
  haptic("light");
  learningFilter = filter;
  if (currentView && currentView.type === "learning") {
    currentView.html = renderLearningCenter();
    render();
  }
}

function setLearningSearch(query) {
  learningSearchQuery = query;
  if (currentView && currentView.type === "learning") {
    currentView.html = renderLearningCenter();
    render();
    const input = document.getElementById("learning-search-input");
    if (input) {
      input.focus();
      input.setSelectionRange(query.length, query.length);
    }
  }
}

function toggleStageExpand(stageNum) {
  haptic("light");
  learningExpandedStages[stageNum] = !learningExpandedStages[stageNum];
  if (currentView && currentView.type === "learning") {
    currentView.html = renderLearningCenter();
    render();
  }
}

async function toggleLearningStage(stageId) {
  haptic("medium");
  try {
    const res = await api("/api/learning/progress/toggle", { stage_id: Number(stageId) });
    if (res.ok) {
      learningState.completed_stages = res.completed_stages || [];
      showToast(res.completed ? "🎉 Bosqich tugatildi deb belgilandi!" : "Bosqich bekor qilindi");
      if (currentView && currentView.type === "learning") {
        currentView.html = renderLearningCenter();
        render();
      }
    }
  } catch (err) {
    showAlert(err.message || "Progressni saqlashda xatolik.");
  }
}

function safeOpenExternal(url) {
  if (!url) return;
  haptic("light");
  try {
    if (window.Telegram && window.Telegram.WebApp && typeof window.Telegram.WebApp.openLink === "function") {
      window.Telegram.WebApp.openLink(url, { try_instant_view: false });
      return;
    }
  } catch (e) {
    console.warn("Telegram openLink fallback:", e);
  }
  try {
    const a = document.createElement("a");
    a.href = url;
    a.target = "_blank";
    a.rel = "noopener noreferrer";
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
      try { document.body.removeChild(a); } catch (ignore) {}
    }, 150);
  } catch (e) {
    window.open(url, "_blank", "noopener,noreferrer");
  }
}

function renderLearningCenter() {
  const stages = learningState.stages || [];
  const resources = learningState.resources || [];
  const tables = learningState.tables || [];
  const completedIds = learningState.completed_stages || [];

  const totalStages = stages.length || 9;
  const completedCount = completedIds.length;
  const progressPct = totalStages ? Math.round((completedCount / totalStages) * 100) : 0;

  const q = (learningSearchQuery || "").trim().toLowerCase();

  // Filter chips
  const filterChips = [
    { id: "all", label: "Barchasi" },
    { id: "stages", label: "Bosqichlar (01-09)" },
    { id: "books", label: "Kitoblar" },
    { id: "standards", label: "Normativlar (ShNQ/GOST)" },
    { id: "projects", label: "Real Loyihalar" },
    { id: "checklist", label: "Interyer Rabochka" },
    { id: "revit", label: "Revit BIM" }
  ];

  // Filtering stages
  const filteredStages = stages.filter(s => {
    if (learningFilter === "books" || learningFilter === "standards" || learningFilter === "projects" || learningFilter === "checklist") {
      const stageRes = resources.filter(r => r.stage_id === s.id);
      if (learningFilter === "books" && !stageRes.some(r => r.resource_type === "book")) return false;
      if (learningFilter === "standards" && !stageRes.some(r => r.resource_type === "standard")) return false;
      if (learningFilter === "projects" && !stageRes.some(r => r.resource_type === "project_album")) return false;
      if (learningFilter === "revit" && !stageRes.some(r => r.resource_type === "revit_guide") && s.stage_number !== 8) return false;
    }
    if (!q) return true;
    const inTitle = (s.title || "").toLowerCase().includes(q);
    const inSub = (s.subtitle || "").toLowerCase().includes(q);
    const inDesc = (s.description || "").toLowerCase().includes(q);
    const inTopics = (s.topics || []).some(t => String(t).toLowerCase().includes(q));
    const inRes = resources.some(r => r.stage_id === s.id && (
      (r.title || "").toLowerCase().includes(q) ||
      (r.author || "").toLowerCase().includes(q) ||
      (r.topic || "").toLowerCase().includes(q)
    ));
    return inTitle || inSub || inDesc || inTopics || inRes;
  });

  // Filtering tables
  const filteredTables = tables.filter(t => {
    if (learningFilter === "stages") return false;
    if (learningFilter === "standards" && t.table_key !== "uzbekistan_norms" && t.table_key !== "spds_gost_standards") return false;
    if (learningFilter === "checklist" && t.table_key !== "interior_drawings_checklist") return false;
    if (learningFilter === "books" && t.table_key !== "top_10_sources") return false;
    if (!q) return true;
    const inTitle = (t.title || "").toLowerCase().includes(q);
    const inSub = (t.subtitle || "").toLowerCase().includes(q);
    const inRows = (t.rows || []).some(row => row.some(cell => String(cell).toLowerCase().includes(q)));
    return inTitle || inSub || inRows;
  });

  return `
    <div class="learning-container">
      <div class="back-btn" onclick="closeDetail()">← Kutubxonaga qaytish</div>

      <!-- HERO BANNER -->
      <div class="learning-hero">
        <div class="learning-hero-badge">YOSHUZBEKK ACADEMY • KNOWLEDGE CENTER</div>
        <h1 class="learning-hero-title">Arxitektura loyihalash va professional loyiha hujjatlari</h1>
        <p class="learning-hero-desc">
          O‘zbekiston sharoitida arxitektura loyihalash, ishchi hujjatlar, grafik rasmiylashtirish, komponovka, spetsifikatsiya va normativ hujjatlarni bosqichma-bosqich o‘rganish.
        </p>

        <!-- PROGRESS CARD -->
        <div class="learning-progress-card">
          <div class="learning-progress-header">
            <span class="learning-progress-label">Sizning o‘rganish progressi</span>
            <span class="learning-progress-count">${completedCount} / ${totalStages} bosqich (${progressPct}%)</span>
          </div>
          <div class="learning-progress-track">
            <div class="learning-progress-bar" style="width: ${progressPct}%;"></div>
          </div>
        </div>
      </div>

      <!-- SEARCH & FILTER -->
      <div class="learning-controls">
        <div class="learning-search-wrap">
          <span class="learning-search-icon">🔍</span>
          <input
            id="learning-search-input"
            class="learning-search-input"
            type="text"
            placeholder="Mavzu, kitob, normativ yoki spetsifikatsiyani qidiring..."
            value="${escapeHtml(learningSearchQuery)}"
            oninput="setLearningSearch(this.value)"
          />
        </div>

        <div class="learning-filter-chips">
          ${filterChips.map(f => `
            <div class="learning-chip ${learningFilter === f.id ? "active" : ""}" onclick="setLearningFilter('${f.id}')">
              ${f.label}
            </div>
          `).join("")}
        </div>
      </div>

      <!-- STAGES ACCORDION LIST -->
      ${filteredStages.length ? `
        <div class="learning-sec-label" style="margin-bottom: 12px;">ROADMAP: 01 DAN 09 BOSQICHLAR</div>
        ${filteredStages.map(stage => {
          const isExpanded = Boolean(learningExpandedStages[stage.stage_number]);
          const isCompleted = completedIds.includes(stage.id);
          const stageRes = resources.filter(r => r.stage_id === stage.id);

          return `
            <div class="learning-stage-card ${isExpanded ? "expanded" : ""} ${isCompleted ? "completed" : ""}">
              <div class="learning-stage-header" onclick="toggleStageExpand(${stage.stage_number})">
                <div class="learning-stage-info">
                  <div class="learning-stage-top-meta">
                    <span class="learning-stage-num">${String(stage.stage_number).padStart(2, "0")}-BOSQICH</span>
                    ${isCompleted ? `<span class="learning-completed-badge">✓ Tugatildi</span>` : ""}
                  </div>
                  <div class="learning-stage-title">${escapeHtml(stage.title)}</div>
                  <div class="learning-stage-subtitle">${escapeHtml(stage.subtitle || "")}</div>
                </div>
                <div class="learning-stage-chevron">▼</div>
              </div>

              <div class="learning-stage-body">
                <div class="learning-sec-label">Tushuntirish:</div>
                <div class="learning-stage-desc">${escapeHtml(stage.description || "")}</div>

                ${Array.isArray(stage.topics) && stage.topics.length ? `
                  <div class="learning-sec-label">Nimalarni o'rganasiz:</div>
                  <div class="learning-topics-box">
                    <ul class="learning-topics-list">
                      ${stage.topics.map(t => `<li>${escapeHtml(t)}</li>`).join("")}
                    </ul>
                  </div>
                ` : ""}

                ${stageRes.length ? `
                  <div class="learning-sec-label">Bosqich manbalari va adabiyotlari (${stageRes.length} ta):</div>
                  <div class="learning-res-list">
                    ${stageRes.map(res => `
                      <div class="learning-res-card">
                        <div class="learning-res-top">
                          <div class="learning-res-title">${escapeHtml(res.title)}</div>
                          <span class="learning-res-tag">${escapeHtml(res.resource_type)}</span>
                        </div>
                        <div class="learning-res-meta">
                          ${res.author ? `<span>Muallif: <b>${escapeHtml(res.author)}</b></span> · ` : ""}
                          ${res.year ? `<span>Yil: ${escapeHtml(res.year)}</span> · ` : ""}
                          ${res.language ? `<span>Til: ${escapeHtml(res.language.toUpperCase())}</span>` : ""}
                        </div>
                        ${res.topic ? `<div style="font-size: 12px; color: var(--text-secondary); margin-bottom: 6px;">Mavzu: ${escapeHtml(res.topic)}</div>` : ""}
                        ${res.benefit_description ? `
                          <div class="learning-res-benefit">
                            <b>Foydasi:</b> ${escapeHtml(res.benefit_description)}
                          </div>
                        ` : ""}
                        <div class="learning-res-actions">
                          ${(() => {
                            const isSame = res.pdf_url && res.web_url && (res.pdf_url === res.web_url);
                            if (isSame) {
                              let label = "🌐 Manbani to‘liq ochish →";
                              if (res.resource_type === "standard") {
                                label = "🏛️ Rasmiy me'yor / Hujjatni ochish →";
                              } else if (res.resource_type === "revit_guide") {
                                label = "📐 ADSK Shablon / Qo‘llanmani ochish →";
                              } else if (res.resource_type === "project_album") {
                                label = "📑 Real Loyiha Albomini ko‘rish →";
                              } else if (res.resource_type === "book") {
                                label = "📖 Kitobni o‘qish / Yuklab olish →";
                              }
                              return `
                                <button class="learning-action-btn primary" onclick="safeOpenExternal('${escapeJsString(res.pdf_url)}')">
                                  ${label}
                                </button>
                              `;
                            }

                            let html = "";
                            if (res.pdf_url) {
                              const isPdfFile = res.pdf_url.toLowerCase().endsWith(".pdf") || res.pdf_url.includes(".pdf");
                              let pdfLabel = isPdfFile ? "📄 PDFni o‘qish / Yuklash →" : "📄 To‘g‘ridan-to‘g‘ri o‘qish (PDF) →";
                              if (res.resource_type === "revit_guide" && res.pdf_url.includes("github")) {
                                pdfLabel = "💻 BIM 2.0 GitHub Repo →";
                              } else if (res.resource_type === "standard" && res.pdf_url.includes("lex.uz")) {
                                pdfLabel = "🏛️ Lex.uz Hujjat matni →";
                              }
                              html += `
                                <button class="learning-action-btn primary" onclick="safeOpenExternal('${escapeJsString(res.pdf_url)}')">
                                  ${pdfLabel}
                                </button>
                              `;
                            }
                            if (res.web_url) {
                              let webLabel = "🌐 Online manba →";
                              if (res.resource_type === "standard" && res.web_url.includes("stroyinf.ru")) {
                                webLabel = "🌐 Standartning to‘liq matni →";
                              } else if (res.resource_type === "book" && res.web_url.includes("unilibrary")) {
                                webLabel = "📚 UniLibrary.uz sahifasi →";
                              } else if (res.resource_type === "book" && res.web_url.includes("studfile")) {
                                webLabel = "📖 Studfile online o‘qish →";
                              } else if (res.resource_type === "project_album" && res.web_url.includes("dwg.ru")) {
                                webLabel = "📐 DWG.RU loyiha bazasi →";
                              } else if (res.resource_type === "revit_guide" && res.web_url.includes("bim2b")) {
                                webLabel = "📐 BIM2B rasmiy shablonlar →";
                              }
                              html += `
                                <button class="learning-action-btn" onclick="safeOpenExternal('${escapeJsString(res.web_url)}')">
                                  ${webLabel}
                                </button>
                              `;
                            }
                            return html;
                          })()}
                        </div>
                      </div>
                    `).join("")}
                  </div>
                ` : ""}

                <div class="learning-stage-footer">
                  <button class="learning-toggle-btn ${isCompleted ? "completed" : ""}" onclick="toggleLearningStage(${stage.id})">
                    ${isCompleted ? "✓ Tugatildi (Bekor qilish)" : "○ Bosqichni tugatildi deb belgilash"}
                  </button>
                </div>
              </div>
            </div>
          `;
        }).join("")}
      ` : ""}

      <!-- TABLES SECTION -->
      ${filteredTables.length ? `
        <div class="learning-sec-label" style="margin: 28px 0 14px;">STANDARTLAR, NORMATIVLAR VA ASOSIY JADVALLAR</div>
        ${filteredTables.map(tbl => `
          <div class="learning-table-card">
            <div class="learning-table-header">
              <div class="learning-table-title">${escapeHtml(tbl.title)}</div>
              ${tbl.subtitle ? `<div class="learning-table-subtitle">${escapeHtml(tbl.subtitle)}</div>` : ""}
            </div>
            <div class="learning-table-scroll">
              <table class="learning-table">
                <thead>
                  <tr>
                    ${(tbl.columns || []).map(col => `<th>${escapeHtml(col)}</th>`).join("")}
                  </tr>
                </thead>
                <tbody>
                  ${(tbl.rows || []).map(row => `
                    <tr>
                      ${row.map((cell, idx) => {
                        const cellStr = String(cell || "");
                        if (cellStr.startsWith("http://") || cellStr.startsWith("https://")) {
                          let linkText = "Ochish ↗";
                          if (cellStr.includes("lex.uz")) linkText = "Lex.uz ↗";
                          else if (cellStr.includes("stroyinf.ru") || cellStr.includes("allgosts.ru")) linkText = "GOST Matni ↗";
                          else if (cellStr.includes(".pdf")) linkText = "PDF ↗";
                          return `
                            <td>
                              <a class="learning-table-link" href="${escapeHtml(cellStr)}" target="_blank" rel="noopener noreferrer" onclick="safeOpenExternal('${escapeJsString(cellStr)}'); return false;">
                                ${linkText}
                              </a>
                            </td>
                          `;
                        }
                        if (cellStr === "AMALDA") {
                          return `<td><span class="learning-status-badge active">AMALDA</span></td>`;
                        }
                        if (cellStr === "BEKOR QILINGAN") {
                          return `<td><span class="learning-status-badge deprecated">BEKOR QILINGAN</span></td>`;
                        }
                        return `<td>${escapeHtml(cellStr)}</td>`;
                      }).join("")}
                    </tr>
                  `).join("")}
                </tbody>
              </table>
            </div>
          </div>
        `).join("")}
      ` : ""}

      ${!filteredStages.length && !filteredTables.length ? `
        <div class="empty-box" style="margin-top: 30px;">
          Hech narsa topilmadi. Qidiruv so'zini o'zgartirib ko'ring yoki boshqa filtrni tanlang.
        </div>
      ` : ""}
    </div>
  `;
}

// Admin Learning Management UI
function renderAdminLearning() {
  const stages = learningState.stages || [];
  const resources = learningState.resources || [];
  const tables = learningState.tables || [];

  return `
    <div style="margin-bottom: 20px;">
      <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px;">
        <div>
          <h3 style="margin: 0; font-size: 18px;">📚 O‘rganish Bazasi Boshqaruvi</h3>
          <p style="margin: 4px 0 0; font-size: 12.5px; color: var(--text-secondary);">
            Arxitektura va ishchi loyihalar o‘quv markazi ma'lumotlarini boshqarish
          </p>
        </div>
        <button class="btn" style="width: auto; padding: 8px 14px; font-size: 12.5px; margin: 0;" onclick="openAddLearningResourceModal()">
          ➕ Yangi Resurs
        </button>
      </div>

      <div class="admin-stats-grid" style="grid-template-columns: repeat(3, 1fr); margin-bottom: 20px;">
        <div class="stat-card">
          <div class="stat-num">${stages.length}</div>
          <div class="stat-label">Bosqichlar (Roadmap)</div>
        </div>
        <div class="stat-card">
          <div class="stat-num">${resources.length}</div>
          <div class="stat-label">Kitoblar & Standartlar</div>
        </div>
        <div class="stat-card">
          <div class="stat-num">${tables.length}</div>
          <div class="stat-label">Me'yoriy Jadvallar</div>
        </div>
      </div>

      <div class="section-title">01..09 Bosqichlar va Resurslar</div>
      <div style="display: flex; flex-direction: column; gap: 12px;">
        ${stages.map(stage => {
          const stageRes = resources.filter(r => r.stage_id === stage.id);
          return `
            <div style="background: var(--bg-surface); border: 1px solid var(--border); border-radius: var(--radius-md); padding: 14px;">
              <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 8px;">
                <div>
                  <span style="font-size: 11px; font-weight: 800; color: var(--accent); text-transform: uppercase;">
                    ${String(stage.stage_number).padStart(2, "0")}-BOSQICH
                  </span>
                  <div style="font-weight: 750; font-size: 15px; color: var(--text-primary); margin: 2px 0;">
                    ${escapeHtml(stage.title)}
                  </div>
                  <div style="font-size: 12px; color: var(--text-secondary);">
                    ${escapeHtml(stage.subtitle || "")}
                  </div>
                </div>
                <div style="display: flex; gap: 6px;">
                  <button class="admin-small-btn" onclick="openAddLearningResourceModal(${stage.id})">
                    ➕ Resurs qo‘shish
                  </button>
                </div>
              </div>

              ${stageRes.length ? `
                <div style="border-top: 1px solid var(--border); padding-top: 10px; margin-top: 10px; display: flex; flex-direction: column; gap: 6px;">
                  ${stageRes.map(res => `
                    <div style="display: flex; justify-content: space-between; align-items: center; background: var(--bg-surface-elevated, rgba(0,0,0,0.02)); padding: 8px 12px; border-radius: 8px; font-size: 12.5px;">
                      <div>
                        <b>${escapeHtml(res.title)}</b>
                        <span style="color: var(--text-secondary); margin-left: 6px;">(${escapeHtml(res.resource_type)} · ${escapeHtml(res.year || '')})</span>
                      </div>
                      <div style="display: flex; gap: 6px;">
                        ${res.pdf_url ? `<button class="admin-small-btn" onclick="safeOpenExternal('${escapeJsString(res.pdf_url)}')">PDF ↗</button>` : ""}
                        <button class="admin-small-btn" style="background: rgba(235,59,59,0.8);" onclick="deleteLearningResource(${res.id})">🗑️</button>
                      </div>
                    </div>
                  `).join("")}
                </div>
              ` : `<div style="font-size: 12px; color: var(--text-secondary); margin-top: 6px;">Ushbu bosqichda alohida resurs biriktirilmagan.</div>`}
            </div>
          `;
        }).join("")}
      </div>
    </div>
  `;
}

function openAddLearningResourceModal(defaultStageId = null) {
  const stages = learningState.stages || [];
  const modal = document.createElement("div");
  modal.className = "modal-overlay";
  modal.innerHTML = `
    <div class="modal-card" style="max-width: 480px; width: 92vw; max-height: 85vh; overflow-y: auto;">
      <div class="modal-title">➕ Yangi O‘rganish Resursi</div>
      <div style="display: flex; flex-direction: column; gap: 12px; margin: 16px 0;">
        <div class="apple-field">
          <label>Qaysi bosqichga biriktiriladi?</label>
          <select id="lr-new-stage" class="apple-input">
            <option value="">-- Bosqichsiz (Umumiy) --</option>
            ${stages.map(s => `
              <option value="${s.id}" ${defaultStageId === s.id ? "selected" : ""}>
                ${String(s.stage_number).padStart(2, "0")} — ${escapeHtml(s.title)}
              </option>
            `).join("")}
          </select>
        </div>

        <div class="apple-field">
          <label>Resurs / Kitob nomi *</label>
          <input id="lr-new-title" class="apple-input" type="text" placeholder="Masalan: Строительное черчение">
        </div>

        <div class="apple-field">
          <label>Muallif</label>
          <input id="lr-new-author" class="apple-input" type="text" placeholder="Masalan: Будасов Б.В.">
        </div>

        <div class="apple-field">
          <label>Yil</label>
          <input id="lr-new-year" class="apple-input" type="text" placeholder="Masalan: 2003">
        </div>

        <div class="apple-field">
          <label>Til</label>
          <select id="lr-new-lang" class="apple-input">
            <option value="uz">O‘zbekcha (UZ)</option>
            <option value="ru" selected>Ruscha (RU)</option>
            <option value="en">Inglizcha (EN)</option>
          </select>
        </div>

        <div class="apple-field">
          <label>Resurs turi</label>
          <select id="lr-new-type" class="apple-input">
            <option value="book" selected>Kitob / Darslik</option>
            <option value="standard">Normativ / Standart (ShNQ/GOST)</option>
            <option value="project_album">Real Loyiha Albomi (PDF)</option>
            <option value="revit_guide">Revit / BIM Qo‘llanma</option>
            <option value="checklist">Checklist / Ma'lumotnoma</option>
          </select>
        </div>

        <div class="apple-field">
          <label>Asosiy mavzusi</label>
          <input id="lr-new-topic" class="apple-input" type="text" placeholder="Mavzusi">
        </div>

        <div class="apple-field">
          <label>Amaliy foydasi (Qisqa izoh)</label>
          <textarea id="lr-new-benefit" class="apple-input" rows="2" placeholder="O‘quvchiga nima foyda beradi..."></textarea>
        </div>

        <div class="apple-field">
          <label>PDF URL havolasi</label>
          <input id="lr-new-pdf" class="apple-input" type="url" placeholder="https://...">
        </div>

        <div class="apple-field">
          <label>Online manba URL havolasi</label>
          <input id="lr-new-web" class="apple-input" type="url" placeholder="https://...">
        </div>
      </div>

      <div class="modal-actions">
        <button type="button" class="modal-btn cancel" onclick="this.closest('.modal-overlay').remove()">Bekor qilish</button>
        <button type="button" class="modal-btn confirm" onclick="submitAddLearningResource()">💾 Saqlash</button>
      </div>
    </div>
  `;
  document.body.appendChild(modal);
}

async function submitAddLearningResource() {
  const stageId = document.getElementById("lr-new-stage")?.value || null;
  const title = document.getElementById("lr-new-title")?.value.trim();
  const author = document.getElementById("lr-new-author")?.value.trim();
  const year = document.getElementById("lr-new-year")?.value.trim();
  const language = document.getElementById("lr-new-lang")?.value || "ru";
  const resourceType = document.getElementById("lr-new-type")?.value || "book";
  const topic = document.getElementById("lr-new-topic")?.value.trim();
  const benefit = document.getElementById("lr-new-benefit")?.value.trim();
  const pdfUrl = document.getElementById("lr-new-pdf")?.value.trim();
  const webUrl = document.getElementById("lr-new-web")?.value.trim();

  if (!title) return showAlert("Resurs nomi kiritilishi shart!");

  try {
    haptic("medium");
    await adminApi("/api/admin/learning/resource/save", {
      stage_id: stageId ? Number(stageId) : null,
      title,
      author,
      year,
      language,
      resource_type: resourceType,
      topic,
      benefit_description: benefit,
      pdf_url: pdfUrl,
      web_url: webUrl,
      is_free: true,
      is_pro: false
    });
    showToast("Resurs muvaffaqiyatli saqlandi!");
    document.querySelector(".modal-overlay")?.remove();
    await loadLearningContent();
    renderAdminPanel();
  } catch (err) {
    showAlert(err.message || "Saqlashda xatolik");
  }
}

async function deleteLearningResource(id) {
  showConfirm(
    "Resurs o‘chirilsinmi?",
    "Ushbu resurs o‘quv markazidan butunlay olib tashlanadi.",
    "Ha, o‘chirish",
    async () => {
      await adminApi("/api/admin/learning/resource/delete", { id: Number(id) });
      showToast("Resurs o‘chirildi!");
      await loadLearningContent();
      renderAdminPanel();
    }
  );
}


function render() {
  if (!app) return;

  // Foydalanish qoidalarini qabul qilmagan foydalanuvchini bloklaymiz (Onboarding gate)
  if (!state.terms_accepted && !state.is_admin) {
    app.innerHTML = `
      <div class="screen">
        ${renderTermsOnboardingHtml()}
      </div>
    `;
    updateTelegramBackButton();
    return;
  }

  const body = currentView ? currentView.html : renderTab();
  app.innerHTML = `
    <div class="screen">
      ${body}
    </div>
    ${!currentView ? renderNav() : ""}
  `;
  updateTelegramBackButton();
}

// ======================================================
// APPLICATION INITIALIZATION
// ======================================================

(async () => {
  try {
    await loadAuth();
    if (!state.registered && !state.is_admin) {
      renderRegistration();
      return;
    }
    await loadContent();
    initHeartbeat();
  } catch (error) {
    console.error("APP START ERROR:", error);
    if (app) {
      app.innerHTML = `
        <div class="page" style="padding-top: 60px; text-align: center;">
          <div class="splash-logo" style="margin: 0 auto 16px;">!</div>
          <h3>Bog'lanishda xatolik</h3>
          <p style="color: var(--text-secondary); margin: 10px 0 20px;">
            ${escapeHtml(error.message || "Mini App faqat Telegram ichida ishlaydi.")}
          </p>
          <button class="btn" style="max-width: 240px; margin: 0 auto;" onclick="location.reload()">
            🔄 Qayta yuklash
          </button>
        </div>
      `;
    }
  }
})();


// ======================================================
// COURSE ACCESS MODAL & FLOW (PULLIK KURSLARGA A'ZO BO'LISH)
// ======================================================

async function openCourseAccessModal(courseId) {
  haptic("medium");
  const cid = Number(courseId) || 1;
  const course = (state.courses || []).find(c => Number(c.id) === cid) ||
    (courseModulesData && Number(courseModulesData.course?.id) === cid ? courseModulesData.course : {
      id: cid,
      title: "INTPRO — Revit dasturida interyer loyihalash",
      subtitle: "Interyer Loyihalash & BIM Modellashtirish",
      price: "1 500 000 so'm",
      total_modules: 11,
      total_lessons: 140
    });

  const priceText = course.discount_price && course.is_discount_active
    ? `${course.discount_price} (Eski narxi: ${course.price})`
    : (course.price || "1 500 000 so'm");

  const contactTg = (state.settings?.contact_telegram || "@texnik_uzb").replace(/^@/, "");

  currentView = {
    html: `
      <div class="page">
        <div class="back-btn" onclick="closeDetail()">← Ortga qaytish</div>
        
        <div style="background:linear-gradient(135deg, rgba(41,121,255,0.12), rgba(0,230,118,0.06)); border:1.5px solid var(--accent); border-radius:var(--radius-lg); padding:20px; margin-bottom:20px; text-align:center;">
          <div style="font-size:36px; margin-bottom:8px;">💎</div>
          <div class="page-title" style="margin-bottom:6px; font-size:18px;">${escapeHtml(course.title)}</div>
          <p style="color:var(--text-secondary); font-size:13px; margin-bottom:14px;">${escapeHtml(course.subtitle || "Mukammal professional Revit kursi")}</p>
          
          <div style="display:inline-block; background:var(--bg-surface); padding:8px 18px; border-radius:24px; border:1px solid var(--border); font-size:16px; font-weight:800; color:var(--accent); margin-bottom:14px;">
            💰 Narxi: ${escapeHtml(priceText)}
          </div>

          <div style="text-align:left; background:var(--bg-surface); border:1px solid var(--border); border-radius:var(--radius-md); padding:14px; margin-bottom:18px; font-size:12.5px; line-height:1.6; color:var(--text-secondary);">
            <div style="font-weight:750; color:var(--text-primary); margin-bottom:6px;">Kurs a'zolariga nimalar beriladi:</div>
            <div>✅ <b>${course.total_modules || 11} ta modul</b> va <b>${course.total_lessons || 140} ta video dars</b>ga 1 yil to'liq kirish</div>
            <div>✅ Revit loyiha andozalari, oilalari (family) va ishchi fayllar</div>
            <div>✅ Har bir dars ostida ustoz bilan to'g'ridan-to'g'ri savol-javob</div>
            <div>✅ Amaliy uy vazifalarini ustoz tomonidan tekshirish va baholash</div>
            <div>✅ Kurs yakunida rasmiy sertifikat va portfolio himoyasi</div>
          </div>

          <div style="display:flex; flex-direction:column; gap:10px;">
            <button class="btn" style="margin-bottom:0; background:linear-gradient(135deg, #00c853, #009624);" onclick="submitCourseAccessRequest(${cid})">
              🚀 Kursga a'zo bo'lish so'rovini yuborish
            </button>

            <button class="btn" style="margin-bottom:0; background:linear-gradient(135deg, #0088cc, #2979ff);" onclick="openDirectAdminTelegram('${escapeJsString(contactTg)}', 'Assalomu alaykum! Men "${escapeJsString(course.title)}" kursiga a\'zo bo\'lmoqchiman.')">
              💬 Adminga Telegram'dan yozish (@${escapeHtml(contactTg)})
            </button>

            <button class="btn secondary" style="margin-bottom:0;" onclick="openCourseCatalog(${cid})">
              📋 Modullar mundarijasini ko'rish
            </button>
          </div>
        </div>
      </div>
    `
  };
  render();
}

async function submitCourseAccessRequest(courseId) {
  try {
    haptic("medium");
    const res = await api("/api/request-access", { course_id: courseId });
    if (res.ok) {
      showToast(res.already_pending ? "So'rovingiz adminga yetkazilgan!" : "So'rov adminga muvaffaqiyatli yuborildi!");
      showAlert("So'rovingiz adminga yuborildi! Tez orada admin siz bilan bog'lanadi va kursga to'liq ruxsat ochiladi.");
    } else {
      showAlert(res.error || "So'rov yuborishda xatolik.");
    }
  } catch (err) {
    showAlert(err.message || "So'rov yuborishda xatolik yuz berdi.");
  }
}

async function checkAdminTelegramVideo(inputId, resultId) {
  const input = document.getElementById(inputId);
  const resultDiv = document.getElementById(resultId);
  if (!input || !resultDiv) return;
  const val = input.value.trim();
  if (!val) {
    showAlert("Telegram havolasi yoki chat_id/message_id ni kiriting!");
    return;
  }
  resultDiv.style.display = "block";
  resultDiv.innerHTML = "<span style='color:var(--text-secondary);'>⏳ Telegram xabari tekshirilmoqda...</span>";
  try {
    const res = await adminApi("/api/admin/telegram/check-video", { telegram_url: val });
    if (res.ok) {
      const mb = res.file_size ? (res.file_size / (1024 * 1024)).toFixed(1) + " MB" : "";
      const chan = res.channel_title ? `[${res.channel_title}]` : "";
      const sizeTxt = mb ? `(${mb})` : "";
      resultDiv.innerHTML = `
        <div style="background:rgba(52,199,89,0.1); border:1px solid rgba(52,199,89,0.3); border-radius:8px; padding:8px 10px; margin-top:4px;">
          <div style="color:#34c759; font-weight:700; font-size:12px;">✓ Video ulandi: ${escapeHtml(chan)} ${escapeHtml(res.file_name)} ${sizeTxt}</div>
          <div style="color:var(--text-secondary); font-size:11px; margin-top:2px;">Chat ID: ${escapeHtml(res.chat_id)} | Post #${res.message_id}</div>
        </div>
      `;
    } else {
      resultDiv.innerHTML = `
        <div style="background:rgba(255,59,48,0.08); border:1px solid rgba(255,59,48,0.25); border-radius:8px; padding:10px 12px; margin-top:4px;">
          <div style="color:#ff3b30; font-weight:700; font-size:12.5px; margin-bottom:4px;">✕ ${escapeHtml(res.error || "Telegram xabari topilmadi")}</div>
          ${res.details ? `<div style="color:var(--text-secondary); font-size:11px; margin-bottom:4px;"><strong>Telegram javobi:</strong> ${escapeHtml(res.details)}</div>` : ""}
          ${res.hint ? `<div style="color:#ff9500; font-size:11.5px; font-weight:600; line-height:1.4;">💡 Nima qilish kerak: ${escapeHtml(res.hint)}</div>` : ""}
        </div>
      `;
    }
  } catch (err) {
    resultDiv.innerHTML = `<span style="color:#ff3b30; font-weight:600;">✕ Tekshirishda xato: ${escapeHtml(err.message)}</span>`;
  }
}

async function saveStudentVideoPlatform(studentId) {
  const select = document.getElementById("student-video-platform");
  if (!select) return;
  const platform = select.value;
  try {
    haptic("medium");
    await adminApi(`/api/admin/student/${Number(studentId)}/video-platform`, { platform });
    showToast("Talabaning video platformasi yangilandi!");
  } catch (err) {
    showAlert(err.message || "Video platformasini saqlashda xato yuz berdi.");
  }
}

