function showAppModalHtml(html) {
  closeAdminModal();
  const wrap = document.createElement('div');
  wrap.id = 'app-dynamic-modal-wrap';
  wrap.innerHTML = html;
  document.body.appendChild(wrap);
}

function closeAdminModal() {
  const m = document.getElementById('app-dynamic-modal-wrap');
  if (m) m.remove();
}


// ======================================================
// JARAYON (INTERYER VA REMONT BOSQICHLARI) FRONTEND ENGINE
// 23 Kategoriya, 220 ta batafsil bilim kartalari, qidiruv va progress
// ======================================================

var processState = {
  loaded: false,
  loading: false,
  activeHub: 'hub', // 'hub' | 'remont' | 'design' | 'rabochka'
  categories: [],
  items: [],
  designSteps: [],
  activeDesignStep: null,
  rabochkaSteps: [],
  activeRabochkaStep: null,
  activeCategoryId: null,
  activeCategorySlug: null,
  searchQuery: "",
  activeFilter: "all",
  panelOpen: false,
  hubFilter: "all",
  currentView: "categories", // 'categories' | 'category_detail' | 'item_detail'
  activeItemDetail: null,
  viewedIds: new Set(),
  savedIds: new Set(),
  completedChecklists: {}, // { [itemId]: [0, 1] }
  stats: { total: 220, viewed: 0 }
};

// ANIMATSIYALI PLACEHOLDER (JARAYON)
const PROCESS_PH_WORDS = [
  "Elektr montaj",
  "Devorni tayyorlash",
  "Santexnika",
  "Gipsokarton",
  "Bo‘yash",
  "Pol yotqizish",
  "Mebel rejasi",
  "Yoritish",
  "O‘lchov olish",
  "3D vizualizatsiya"
];
let _procPhIdx = 0, _procPhText = "", _procPhPhase = "typing", _procPhTimer = null;

function ensureProcessPlaceholderTicker() {
  if (_procPhTimer) return;
  const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const step = () => {
    const el = document.getElementById("proc-ph-word");
    const inp = document.getElementById("proc-hub-search-input");
    if (!el) { _procPhTimer = null; return; }
    if (document.hidden || (inp && inp.value)) { _procPhTimer = setTimeout(step, 1000); return; }
    const word = PROCESS_PH_WORDS[_procPhIdx % PROCESS_PH_WORDS.length];
    let delay = 90;
    if (reduce) { _procPhText = word; el.textContent = word; _procPhIdx++; _procPhTimer = setTimeout(step, 2400); return; }
    if (_procPhPhase === "typing") {
      _procPhText = word.slice(0, _procPhText.length + 1); delay = 85 + Math.random() * 60;
      if (_procPhText.length >= word.length) { _procPhPhase = "hold"; delay = 1500; }
    } else if (_procPhPhase === "hold") { _procPhPhase = "deleting"; delay = 60; }
    else {
      _procPhText = _procPhText.slice(0, -1); delay = 38;
      if (!_procPhText.length) { _procPhPhase = "typing"; _procPhIdx++; delay = 320; }
    }
    el.textContent = _procPhText;
    _procPhTimer = setTimeout(step, delay);
  };
  _procPhTimer = setTimeout(step, 250);
}

function toggleProcessPanel() {
  haptic("light");
  processState.panelOpen = !processState.panelOpen;
  render();
}

function clearProcessSearch() {
  processState.searchQuery = "";
  render();
}

function setProcessHubFilter(f) {
  haptic("light");
  processState.hubFilter = f || "all";
  render();
}

function renderProcessPanelInnerHtml() {
  const hubOptions = [
    { id: "all", label: "Barchasi" },
    { id: "remont", label: "🔨 Remont jarayoni (23 bosqich)" },
    { id: "design", label: "🎨 Interyer dizayn (9 bosqich)" },
    { id: "rabochka", label: "📐 Ishchi loyiha / Rabochka (21 varaq)" }
  ];

  return `
    <div class="mcat-panel-title">Asosiy yo‘nalishlar</div>
    <div class="mcat-panel-grid">
      ${hubOptions.map(opt => `
        <button type="button" class="mcat-chip ${processState.hubFilter === opt.id ? 'active' : ''}" onclick="setProcessHubFilter('${opt.id}')">
          ${escapeHtml(opt.label)}
        </button>
      `).join('')}
    </div>
  `;
}

function renderProcessActiveFilterHtml() {
  if (!processState.hubFilter || processState.hubFilter === "all") return "";
  const labelMap = {
    remont: "🔨 Remont jarayoni",
    design: "🎨 Interyer dizayn",
    rabochka: "📐 Ishchi loyiha (Rabochka)"
  };
  return `
    <div style="display:flex; flex-wrap:wrap; gap:8px; margin-top:12px;">
      <div class="mcat-active-chip">
        <span class="mcat-active-label">${escapeHtml(labelMap[processState.hubFilter] || processState.hubFilter)}</span>
        <button type="button" class="mcat-active-x" onclick="setProcessHubFilter('all')" aria-label="Filtrni tozalash">✕</button>
      </div>
    </div>
  `;
}

function renderPopularProcessCardsHtml() {
  const items = processState.items || [];
  const remontPicks = [
    items.find(i => (i.slug || '').includes('kalit') || (i.title || '').toLowerCase().includes('kalit')),
    items.find(i => (i.slug || '').includes('santexnika') || (i.title || '').toLowerCase().includes('quvur')),
    items.find(i => (i.slug || '').includes('suvoq') || (i.title || '').toLowerCase().includes('suvoq')),
    items.find(i => (i.slug || '').includes('plitka') || (i.title || '').toLowerCase().includes('keramogranit'))
  ].filter(Boolean);

  const designPicks = (processState.designSteps || []).slice(0, 2);
  const rabochkaPicks = (processState.rabochkaSteps || []).slice(0, 2);

  const cards = [];

  remontPicks.forEach(it => {
    cards.push(`
      <div class="proc-pop-card" onclick="openProcessItemDetail(${Number(it.id)})">
        <div class="proc-pop-top">
          <span class="proc-pop-num">${escapeHtml(it.category_code || '01')}</span>
          <span class="proc-pop-hub">REMONT</span>
        </div>
        <div class="proc-pop-body">
          <div class="proc-pop-title">${escapeHtml(it.title)}</div>
          <div class="proc-pop-cat">${escapeHtml(it.category_title || 'Remont')}</div>
        </div>
      </div>
    `);
  });

  designPicks.forEach(st => {
    cards.push(`
      <div class="proc-pop-card" onclick="openDesignStepDetail('${escapeJsString(st.slug)}')">
        <div class="proc-pop-top">
          <span class="proc-pop-num">${escapeHtml(st.step_number)}</span>
          <span class="proc-pop-hub" style="color:#c4b5fd;">DIZAYN</span>
        </div>
        <div class="proc-pop-body">
          <div class="proc-pop-title">${escapeHtml(st.title)}</div>
          <div class="proc-pop-cat">Interyer dizayn</div>
        </div>
      </div>
    `);
  });

  rabochkaPicks.forEach(rb => {
    cards.push(`
      <div class="proc-pop-card" onclick="openRabochkaStepDetail('${escapeJsString(rb.slug)}')">
        <div class="proc-pop-top">
          <span class="proc-pop-num">${escapeHtml(rb.step_number)}</span>
          <span class="proc-pop-hub" style="color:#67e8f9;">RABOCHKA</span>
        </div>
        <div class="proc-pop-body">
          <div class="proc-pop-title">${escapeHtml(rb.title)}</div>
          <div class="proc-pop-cat">Ishchi chizma</div>
        </div>
      </div>
    `);
  });

  return cards.join('');
}

function renderProcessSearchResultsHtml() {
  const q = (processState.searchQuery || "").toLowerCase().trim();
  if (!q) return "";

  const matchingItems = (processState.items || []).filter(it =>
    (it.title || "").toLowerCase().includes(q) ||
    (it.short_description || "").toLowerCase().includes(q) ||
    (it.category_title || "").toLowerCase().includes(q)
  );

  const matchingDesign = (processState.designSteps || []).filter(st =>
    (st.title || "").toLowerCase().includes(q) ||
    (st.lead || "").toLowerCase().includes(q) ||
    (st.purpose || "").toLowerCase().includes(q)
  );

  const matchingRabochka = (processState.rabochkaSteps || []).filter(rb =>
    (rb.title || "").toLowerCase().includes(q) ||
    (rb.lead || "").toLowerCase().includes(q) ||
    (rb.content_summary || "").toLowerCase().includes(q)
  );

  const total = matchingItems.length + matchingDesign.length + matchingRabochka.length;

  if (total === 0) {
    return `
      <div class="mcat-empty" style="margin-top:20px;">
        <div class="mcat-empty-ico">🔍</div>
        <div class="mcat-empty-title">Jarayon topilmadi</div>
        <div class="mcat-empty-sub">Boshqa so‘z bilan qidirib ko‘ring (masalan: elektr, suvoq, plitka, o‘lchov)</div>
        <button type="button" class="mcat-chip" style="margin-top:12px;" onclick="clearProcessSearch()">
          Qidiruvni tozalash
        </button>
      </div>
    `;
  }

  return `
    <div style="margin-top:18px;">
      <div class="mcat-section-title" style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;">
        <span>Qidiruv natijalari</span>
        <span style="font-size:12px; font-weight:500; color:var(--text-secondary);">${total} ta jarayon</span>
      </div>

      <div class="proc-items-list">
        ${matchingDesign.map(st => `
          <div class="proc-item-card" onclick="openDesignStepDetail('${escapeJsString(st.slug)}')">
            <div class="proc-item-num" style="background: rgba(139, 92, 246, 0.12); color: #a78bfa;">${st.step_number}</div>
            <div class="proc-item-body">
              <div class="proc-item-title-row">
                <h4 class="proc-item-title">${escapeHtml(st.title)}</h4>
                <span class="lib-file-badge" style="background:rgba(139, 92, 246, 0.15); color:#c4b5fd;">DIZAYN</span>
              </div>
              <p class="proc-item-short">${escapeHtml(st.lead || '')}</p>
            </div>
          </div>
        `).join('')}

        ${matchingRabochka.map(rb => `
          <div class="proc-item-card" onclick="openRabochkaStepDetail('${escapeJsString(rb.slug)}')">
            <div class="proc-item-num" style="background: rgba(6, 182, 212, 0.12); color: #22d3ee;">${rb.step_number}</div>
            <div class="proc-item-body">
              <div class="proc-item-title-row">
                <h4 class="proc-item-title">${escapeHtml(rb.title)}</h4>
                <span class="lib-file-badge" style="background:rgba(6, 182, 212, 0.15); color:#67e8f9;">RABOCHKA</span>
              </div>
              <p class="proc-item-short">${escapeHtml(rb.lead || '')}</p>
            </div>
          </div>
        `).join('')}

        ${matchingItems.map((it, idx) => renderProcessItemRowHtml(it, idx)).join('')}
      </div>
    </div>
  `;
}

async function loadProcessData() {
  processState.loading = true;
  try {
    const [catsRes, itemsRes, progRes, designRes, rabochkaRes] = await Promise.all([
      api("/api/process/categories").catch(() => ({ categories: [] })),
      api("/api/process/items", { limit: 400 }).catch(() => ({ items: [] })),
      api("/api/process/user-progress").catch(() => ({ viewed_ids: [], saved_ids: [], checklists: {} })),
      api("/api/process/design/steps").catch(() => ({ steps: [] })),
      api("/api/process/rabochka/steps").catch(() => ({ steps: [] }))
    ]);

    if (catsRes && Array.isArray(catsRes.categories) && catsRes.categories.length) {
      processState.categories = catsRes.categories;
    }
    if (itemsRes && Array.isArray(itemsRes.items) && itemsRes.items.length) {
      processState.items = itemsRes.items;
      processState.stats.total = itemsRes.items.length;
    }
    if (progRes) {
      processState.viewedIds = new Set(progRes.viewed_ids || []);
      processState.savedIds = new Set(progRes.saved_ids || []);
      processState.completedChecklists = progRes.checklists || {};
      processState.stats.viewed = processState.viewedIds.size;
    }
    if (designRes && Array.isArray(designRes.steps) && designRes.steps.length) {
      processState.designSteps = designRes.steps;
    }
    if (rabochkaRes && Array.isArray(rabochkaRes.steps) && rabochkaRes.steps.length) {
      processState.rabochkaSteps = rabochkaRes.steps;
    }
    processState.loaded = true;
  } catch (err) {
    console.error("LOAD PROCESS DATA ERROR:", err);
  } finally {
    processState.loading = false;
    if (libraryActiveSection === "process") {
      render();
    }
  }
}

function setProcessHub(hubId) {
  haptic("light");
  processState.activeHub = hubId || 'hub';
  if (hubId === 'hub') {
    processState.activeDesignStep = null;
    processState.activeRabochkaStep = null;
    processState.currentView = 'categories';
    processState.activeCategoryId = null;
    processState.activeCategorySlug = null;
    processState.activeItemDetail = null;
  }
  render();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function openDesignStepDetail(slugOrNum) {
  haptic("light");
  processState.activeHub = 'design';
  const s = String(slugOrNum).toLowerCase().trim();
  const step = (processState.designSteps || []).find(st => st.slug === s || String(st.step_number) === s);
  if (step) {
    processState.activeDesignStep = step;
    render();
    window.scrollTo({ top: 0, behavior: "smooth" });
  }
}

function closeDesignStepDetail() {
  haptic("light");
  processState.activeDesignStep = null;
  render();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function navigateDesignStep(delta) {
  haptic("light");
  const steps = processState.designSteps || [];
  if (!processState.activeDesignStep || !steps.length) return;
  const currentIdx = steps.findIndex(st => st.slug === processState.activeDesignStep.slug);
  if (currentIdx === -1) return;
  const nextIdx = currentIdx + delta;
  if (nextIdx >= 0 && nextIdx < steps.length) {
    processState.activeDesignStep = steps[nextIdx];
    render();
    window.scrollTo({ top: 0, behavior: "smooth" });
  }
}

function openRabochkaStepDetail(slugOrNum) {
  haptic("light");
  processState.activeHub = 'rabochka';
  const s = String(slugOrNum).toLowerCase().trim();
  const step = (processState.rabochkaSteps || []).find(st => st.slug === s || String(st.step_number) === s);
  if (step) {
    processState.activeRabochkaStep = step;
    render();
    window.scrollTo({ top: 0, behavior: "smooth" });
  }
}

function closeRabochkaStepDetail() {
  haptic("light");
  processState.activeRabochkaStep = null;
  render();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function navigateRabochkaStep(delta) {
  haptic("light");
  const steps = processState.rabochkaSteps || [];
  if (!processState.activeRabochkaStep || !steps.length) return;
  const currentIdx = steps.findIndex(st => st.slug === processState.activeRabochkaStep.slug);
  if (currentIdx === -1) return;
  const nextIdx = currentIdx + delta;
  if (nextIdx >= 0 && nextIdx < steps.length) {
    processState.activeRabochkaStep = steps[nextIdx];
    render();
    window.scrollTo({ top: 0, behavior: "smooth" });
  }
}

function setProcessView(view) {
  haptic("light");
  processState.currentView = view || "categories";
  render();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function setProcessCategory(catSlugOrId) {
  haptic("light");
  const cat = (processState.categories || []).find(c => c.slug === String(catSlugOrId) || Number(c.id) === Number(catSlugOrId));
  if (cat) {
    processState.activeCategoryId = cat.id;
    processState.activeCategorySlug = cat.slug;
  } else {
    processState.activeCategoryId = null;
    processState.activeCategorySlug = String(catSlugOrId);
  }
  processState.currentView = "category_detail";
  processState.searchQuery = "";
  render();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function closeProcessCategoryDetail() {
  haptic("light");
  processState.activeCategoryId = null;
  processState.activeCategorySlug = null;
  processState.currentView = "categories";
  processState.searchQuery = "";
  render();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

async function openProcessItemDetail(idOrSlug) {
  haptic("light");
  processState.activeHub = 'remont';
  const localItem = (processState.items || []).find(i => String(i.id) === String(idOrSlug) || i.slug === String(idOrSlug));
  processState.activeItemDetail = localItem || null;
  processState.currentView = "item_detail";
  render();
  window.scrollTo({ top: 0, behavior: "smooth" });

  // Mark as viewed
  const itemId = localItem ? Number(localItem.id) : Number(idOrSlug);
  if (itemId && !processState.viewedIds.has(itemId)) {
    processState.viewedIds.add(itemId);
    processState.stats.viewed = processState.viewedIds.size;
    api("/api/process/mark-viewed", { item_id: itemId }).catch(() => {});
  }

  // Fetch full detail if needed
  try {
    const res = await api(`/api/process/items/${idOrSlug}`);
    if (res && res.ok && res.item) {
      processState.activeItemDetail = res.item;
      if (processState.currentView === "item_detail") {
        render();
      }
    }
  } catch (e) {
    console.warn("fetch item detail err:", e);
  }
}

function closeProcessItemDetail() {
  haptic("light");
  if (processState.activeCategorySlug) {
    processState.currentView = "category_detail";
  } else {
    processState.currentView = "categories";
  }
  processState.activeItemDetail = null;
  render();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function setProcessFilter(filterName) {
  haptic("light");
  processState.activeFilter = filterName || "all";
  render();
}

let _procSearchTimer = null;
function setProcessSearch(val) {
  clearTimeout(_procSearchTimer);
  _procSearchTimer = setTimeout(() => {
    processState.searchQuery = (val || "").trim();
    render();
  }, 100);
}

function clearProcessSearch() {
  processState.searchQuery = "";
  const inp1 = document.getElementById("proc-search-input");
  if (inp1) inp1.value = "";
  const inp2 = document.getElementById("proc-hub-search-input");
  if (inp2) inp2.value = "";
  render();
}

async function toggleProcessItemSave(itemId) {
  haptic("light");
  itemId = Number(itemId);
  const wasSaved = processState.savedIds.has(itemId);
  if (wasSaved) {
    processState.savedIds.delete(itemId);
  } else {
    processState.savedIds.add(itemId);
  }
  render();

  try {
    const res = await api("/api/process/toggle-save", { item_id: itemId });
    if (!res || !res.ok) throw new Error("Save fail");
    showToast(wasSaved ? "Saqlanganlardan olib tashlandi" : "✓ Saqlandi");
  } catch (e) {
    if (wasSaved) processState.savedIds.add(itemId);
    else processState.savedIds.delete(itemId);
    render();
    showToast("Saqlab bo‘lmadi, qayta urinib ko‘ring");
  }
}

async function toggleProcessChecklist(itemId, checkIdx) {
  haptic("medium");
  itemId = Number(itemId);
  checkIdx = Number(checkIdx);

  if (!processState.completedChecklists[itemId]) {
    processState.completedChecklists[itemId] = [];
  }
  const arr = processState.completedChecklists[itemId];
  const pos = arr.indexOf(checkIdx);
  if (pos > -1) {
    arr.splice(pos, 1);
  } else {
    arr.push(checkIdx);
  }

  // Update in place for zero lag
  const chkBox = document.getElementById(`proc-chk-${itemId}-${checkIdx}`);
  if (chkBox) {
    const isNowChecked = arr.includes(checkIdx);
    chkBox.classList.toggle("checked", isNowChecked);
    const row = chkBox.closest(".proc-checklist-row");
    if (row) row.classList.toggle("done", isNowChecked);
  }

  try {
    await api("/api/process/toggle-checklist", { item_id: itemId, index: checkIdx });
  } catch (e) {
    console.warn("toggle checklist error:", e);
  }
}

